1	function ConvertTo-MtMaesterResult {
2	    <#
3	    .SYNOPSIS
4	    Converts Pester results to the Maester test results format which includes additional information.
5	    #>
6	    [CmdletBinding()]
7	    param(
8	        # The Pester test results returned from Invoke-Pester -PassThru. Omitted when the run had no Pester tests.
9	        [Parameter(Mandatory = $false)]
10	        [AllowNull()]
11	        [psobject] $PesterResults,
12	
13	        # Result rows of the native tests (Invoke-MtNativePlan).
14	        [Parameter(Mandatory = $false)]
15	        [object[]] $NativeRows = @(),
16	
17	        # Wall-clock duration of the native tests.
18	        [Parameter(Mandatory = $false)]
19	        [timespan] $NativeDuration = [timespan]::Zero,
20	
21	        # Optional output files information
22	        [Parameter(Mandatory = $false)]
23	        [psobject] $OutputFiles,
24	
25	        # Optional Invoke-Maester command that was run
26	        [Parameter(Mandatory = $false)]
27	        [string] $InvokeMaesterCommand,
28	
29	        # Optional Pester configuration that was used
30	        [Parameter(Mandatory = $false)]
31	        [psobject] $PesterConfiguration,
32	
33	        # Skip checking PowerShell Gallery for the latest Maester version.
34	        [Parameter(Mandatory = $false)]
35	        [switch] $SkipVersionCheck,
36	
37	        # Build the consolidated affected objects and attach it as the AffectedObjects property.
38	        [Parameter(Mandatory = $false)]
39	        [switch] $IncludeAffectedObjects,
40	
41	        # Optional run context from Invoke-Maester: the selection, the selection plan and the run config.
42	        # Used to add the 3.0 fields (reason codes, family IDs) to each row.
43	        [Parameter(Mandatory = $false)]
44	        [psobject] $RunContext,
45	
46	        # Add Previous: the results of the last run on the tenant in the output folder (Get-MtPreviousResult).
47	        [Parameter(Mandatory = $false)]
48	        [switch] $IncludePrevious
49	    )
50	
51	    $shouldSkipVersionCheck = $SkipVersionCheck.IsPresent
52	    if ($null -eq $PesterResults) {
53	        # No Pester tests in this run: an empty Pester result keeps the rest of the conversion unchanged.
54	        $PesterResults = [PSCustomObject]@{
55	            Tests = @(); Containers = @(); Result = 'Passed'; ExecutedAt = (Get-Date)
56	            Duration = [timespan]::Zero; UserDuration = [timespan]::Zero; DiscoveryDuration = [timespan]::Zero; FrameworkDuration = [timespan]::Zero
57	        }
58	    }
59	
60	    function GetTenantName() {
61	        if (Test-MtConnection Graph) {
62	            $org = Invoke-MtGraphRequest -RelativeUri 'organization'
63	            return $org.DisplayName
64	        } elseif (Test-MtConnection Teams) {
65	            $tenant = Get-CsTenant
66	            return $tenant.DisplayName
67	        } else {
68	            return 'TenantName (not connected to Graph)'
69	        }
70	    }
71	
72	    function GetTenantId() {
73	        if (Test-MtConnection Graph) {
74	            $mgContext = Get-MgContext
75	            return $mgContext.TenantId
76	        } elseif (Test-MtConnection Teams) {
77	            $tenant = Get-CsTenant
78	            return $tenant.TenantId
79	        } else {
80	            return 'TenantId (not connected to Graph)'
81	        }
82	    }
83	
84	    function GetAccount() {
85	        if (Test-MtConnection Graph) {
86	            $mgContext = Get-MgContext
87	            return $mgContext.Account
88	            #} elseif (Test-MtConnection Teams) {
89	            #    $tenant = Get-CsTenant #ToValidate: N/A
90	            #    return $tenant.DisplayName
91	        } else {
92	            return 'Account (not connected to Graph)'
93	        }
94	    }
95	
96	    function GetTestsSorted() {
97	        # Show passed and failed tests first by name then show not run tests
98	        $activeTests = $PesterResults.Tests | Where-Object { $_.Result -eq 'Passed' -or $_.Result -eq 'Failed' } | Sort-Object -Property Name
99	        $inactiveTests = $PesterResults.Tests | Where-Object { $_.Result -ne 'Passed' -and $_.Result -ne 'Failed' } | Sort-Object -Property Name
100	
101	        # Convert to array and add, if not when only one object is returned it doesn't create an array with all items.
102	        return @($activeTests) + @($inactiveTests)
103	    }
104	
105	    function GetFormattedDate($date) {
106	        if (!$IsCoreCLR) {
107	            # Prevent 5.1 date format to json issue
108	            return $date.ToString('o')
109	        } else {
110	            return $date
111	        }
112	    }
113	
114	    function GetMaesterLatestVersion() {
115	        if ($shouldSkipVersionCheck) {
116	            return 'Unknown'
117	        }
118	
119	        $latestVersion = Get-MtLatestModuleVersion -Name Maester -TimeoutSec 10
120	        if ($null -ne $latestVersion) {
121	            return $latestVersion.ToString()
122	        }
123	
124	        return 'Unknown'
125	    }
126	
127	    function GetSystemInfo() {
128	        $systemInfo = [PSCustomObject]@{
129	            MachineName    = [System.Environment]::MachineName
130	            OSDescription  = if ($PSVersionTable.OS) { $PSVersionTable.OS } else { [System.Environment]::OSVersion.VersionString }
131	            OSPlatform     = if ($IsWindows) { 'Windows' } elseif ($IsMacOS) { 'macOS' } elseif ($IsLinux) { 'Linux' } else { 'Windows' }
132	            ProcessorCount = [System.Environment]::ProcessorCount
133	            UserName       = [System.Environment]::UserName
134	            UserDomain     = [System.Environment]::UserDomainName
135	        }
136	        return $systemInfo
137	    }
138	
139	    function GetPowerShellInfo() {
140	        $psInfo = [PSCustomObject]@{
141	            Version  = $PSVersionTable.PSVersion.ToString()
142	            Edition  = $PSVersionTable.PSEdition
143	            Platform = if ($PSVersionTable.Platform) { $PSVersionTable.Platform } else { 'Win32NT' }
144	        }
145	        return $psInfo
146	    }
147	
148	    function GetLoadedModules() {
149	        $modules = Get-Module | ForEach-Object {
150	            [PSCustomObject]@{
151	                Name    = $_.Name
152	                Version = $_.Version.ToString()
153	            }
154	        } | Sort-Object -Property Name
155	        return @($modules)
156	    }
157	
158	    function GetMgContextInfo() {
159	        if (Test-MtConnection Graph) {
160	            $mgContext = Get-MgContext
161	            if ($null -ne $mgContext) {
162	                return [PSCustomObject]@{
163	                    ClientId            = $mgContext.ClientId
164	                    TenantId            = $mgContext.TenantId
165	                    Scopes              = @($mgContext.Scopes)
166	                    AuthType            = [string]$mgContext.AuthType
167	                    TokenCredentialType = [string]$mgContext.TokenCredentialType
168	                    Account             = $mgContext.Account
169	                    AppName             = $mgContext.AppName
170	                    ContextScope        = [string]$mgContext.ContextScope
171	                    Environment         = $mgContext.Environment
172	                    ManagedIdentityId   = $mgContext.ManagedIdentityId
173	                }
174	            }
175	        }
176	        return $null
177	    }
178	
179	    function GetConnectionSummary() {
180	        if ($__MtSession -and $__MtSession.ConnectionSummary) {
181	            return @(foreach ($entry in $__MtSession.ConnectionSummary) {
182	                # A failed connection carries the whole module error. Keep its first line, as the
183	                # console summary does; the full message is in the verbose stream of Connect-Maester.
184	                $detail = "$($entry.Details)" -split "`r?`n" | Where-Object { $_.Trim() } | Select-Object -First 1
185	                $detail = ("$detail" -replace '\s+', ' ').Trim()
186	                if ($detail.Length -gt 200) { $detail = $detail.Substring(0, 197).TrimEnd() + '...' }
187	                [PSCustomObject]@{
188	                    Service = "$($entry.Service)"
189	                    Status  = "$($entry.Status)"
190	                    Details = $detail
191	                }
192	            })
193	        }
194	        return @()
195	    }
196	
197	    function GetLogoAsBase64DataUri($uri) {
198	        try {
199	            $response = Invoke-MgGraphRequest -Uri $uri -OutputType HttpResponseMessage
200	            if ($response.IsSuccessStatusCode) {
201	                $logoBytes = $response.Content.ReadAsByteArrayAsync().GetAwaiter().GetResult()
202	                if ($null -ne $logoBytes -and $logoBytes.Length -gt 0) {
203	                    $base64Logo = [System.Convert]::ToBase64String($logoBytes)
204	                    # Detect content type from response or default to png
205	                    $contentType = $response.Content.Headers.ContentType.MediaType
206	                    if ([string]::IsNullOrEmpty($contentType)) { $contentType = 'image/png' }
207	                    return "data:$contentType;base64,$base64Logo"
208	                }
209	            }
210	        } catch {
211	            Write-Verbose "Could not retrieve logo from $uri : $_"
212	        }
213	        return $null
214	    }
215	
216	    function GetOrganizationLogos() {
217	        $logos = [PSCustomObject]@{
218	            Banner = $null
219	        }
220	
221	        if (Test-MtConnection Graph) {
222	            $mgContext = Get-MgContext
223	            $orgId = $mgContext.TenantId
224	
225	            # Try to get the banner logo
226	            $logos.Banner = GetLogoAsBase64DataUri "/v1.0/organization/$orgId/branding/localizations/default/bannerLogo"
227	        }
228	
229	        # Return null if no logo is available, otherwise return the logos object
230	        if ($null -eq $logos.Banner) {
231	            return $null
232	        }
233	        return $logos
234	    }
235	
236	    function GetPesterConfigInfo($config) {
237	        if ($null -eq $config) { return $null }
238	
239	        # Convert PesterConfiguration to a simple hashtable for JSON serialization
240	        $configInfo = [PSCustomObject]@{
241	            Run          = [PSCustomObject]@{
242	                Path                   = @($config.Run.Path.Value)
243	                ExcludePath            = @($config.Run.ExcludePath.Value)
244	                ScriptBlock            = @($config.Run.ScriptBlock.Value | ForEach-Object { if ($null -ne $_) { $_.ToString() } })
245	                Container              = @($config.Run.Container.Value)
246	                TestExtension          = $config.Run.TestExtension.Value
247	                Exit                   = $config.Run.Exit.Value
248	                Throw                  = $config.Run.Throw.Value
249	                PassThru               = $config.Run.PassThru.Value
250	                SkipRun                = $config.Run.SkipRun.Value
251	                SkipRemainingOnFailure = [string]$config.Run.SkipRemainingOnFailure.Value
252	            }
253	            Filter       = [PSCustomObject]@{
254	                Tag         = @($config.Filter.Tag.Value)
255	                ExcludeTag  = @($config.Filter.ExcludeTag.Value)
256	                Line        = @($config.Filter.Line.Value)
257	                ExcludeLine = @($config.Filter.ExcludeLine.Value)
258	                FullName    = @($config.Filter.FullName.Value)
259	            }
260	            CodeCoverage = [PSCustomObject]@{
261	                Enabled               = $config.CodeCoverage.Enabled.Value
262	                OutputFormat          = $config.CodeCoverage.OutputFormat.Value
263	                OutputPath            = $config.CodeCoverage.OutputPath.Value
264	                OutputEncoding        = $config.CodeCoverage.OutputEncoding.Value
265	                Path                  = @($config.CodeCoverage.Path.Value)
266	                ExcludeTests          = $config.CodeCoverage.ExcludeTests.Value
267	                RecursePaths          = $config.CodeCoverage.RecursePaths.Value
268	                CoveragePercentTarget = $config.CodeCoverage.CoveragePercentTarget.Value
269	                UseBreakpoints        = $config.CodeCoverage.UseBreakpoints.Value
270	                SingleHitBreakpoints  = $config.CodeCoverage.SingleHitBreakpoints.Value
271	            }
272	            TestResult   = [PSCustomObject]@{
273	                Enabled        = $config.TestResult.Enabled.Value
274	                OutputFormat   = $config.TestResult.OutputFormat.Value
275	                OutputPath     = $config.TestResult.OutputPath.Value
276	                OutputEncoding = $config.TestResult.OutputEncoding.Value
277	                TestSuiteName  = $config.TestResult.TestSuiteName.Value
278	            }
279	            Should       = [PSCustomObject]@{
280	                ErrorAction = [string]$config.Should.ErrorAction.Value
281	            }
282	            Debug        = [PSCustomObject]@{
283	                ShowFullErrors         = $config.Debug.ShowFullErrors.Value
284	                WriteDebugMessages     = $config.Debug.WriteDebugMessages.Value
285	                WriteDebugMessagesFrom = @($config.Debug.WriteDebugMessagesFrom.Value)
286	                ShowNavigationMarkers  = $config.Debug.ShowNavigationMarkers.Value
287	                ReturnRawResultObject  = $config.Debug.ReturnRawResultObject.Value
288	            }
289	            Output       = [PSCustomObject]@{
290	                Verbosity           = [string]$config.Output.Verbosity.Value
291	                StackTraceVerbosity = [string]$config.Output.StackTraceVerbosity.Value
292	                CIFormat            = [string]$config.Output.CIFormat.Value
293	                CILogLevel          = [string]$config.Output.CILogLevel.Value
294	                RenderMode          = [string]$config.Output.RenderMode.Value
295	            }
296	        }
297	        return $configInfo
298	    }
299	
300	    #if(Test-MtConnection Graph) { #ToValidate: Issue with -SkipGraphConnect
301	    #    $mgContext = Get-MgContext
302	    #}
303	
304	    #$tenantId = $mgContext.TenantId ?? "Tenant ID (not connected to Graph)"
305	    $tenantId = GetTenantId
306	    $tenantName = GetTenantName
307	    #$account = $mgContext.Account ?? "Account (not connected to Graph)"
308	    $account = GetAccount
309	
310	    $currentVersion = Get-MtModuleVersion
311	    $latestVersion = GetMaesterLatestVersion
312	
313	    $mtTests = @()
314	    $sortedTests = GetTestsSorted
315	
316	    $testIndex = 0
317	
318	    # Tests superseded by a built-in (stale copies of 2.x wrappers) produce no row.
319	    $supersededKeys = @{}
320	    if ($RunContext -and $RunContext.Superseded) {
321	        foreach ($item in $RunContext.Superseded.Items) { $supersededKeys["$($item.File):$($item.Line)"] = $true }
322	    }
323	
324	    $pesterRowAttributes = Get-MtRowAttribute
325	    foreach ($test in $sortedTests) {
326	        if ($supersededKeys.Count -gt 0 -and $test.ScriptBlock.File -and $supersededKeys.ContainsKey("$($test.ScriptBlock.File):$($test.StartLine)")) { continue }
327	        $testIndex++
328	
329	        $name = $test.ExpandedName
330	        $testCustomName = $__MtSession.TestResultDetail[$test.ExpandedName].TestTitle
331	        if (![string]::IsNullOrEmpty($testCustomName)) {
332	            # Use the custom title if it's been provided.
333	            $name = $testCustomName
334	        }
335	
336	        $helpUrl = ''
337	
338	        $start = $name.IndexOf('See https')
339	        # Get the Help Url from the message and the ID
340	        if ($start -gt 0) {
341	            $helpUrl = $name.Substring($start + 4).Trim() #Strip away the "See https://maester.dev" part
342	            $name = $name.Substring(0, $start).Trim() #Strip away the "See https://maester.dev" part
343	        }
344	
345	
346	        # Find the first : and use the first part as $testId and remaining as $testTitle
347	        # If no : is found or if there are spaces before the first : display a warning that the test name is not in the correct format
348	        $titleStart = $name.IndexOf(':')
349	        $testId = $name # Default to the full test name if no split is found
350	        $testTitle = $name # Default to the full test name if no split is found
351	
352	        if ($titleStart -gt 0) {
353	            $testId = $name.Substring(0, $titleStart).Trim()
354	            $testTitle = $name.Substring($titleStart + 1).Trim()
355	        } elseif ($test.Result -ne 'NotRun') {
356	            Write-Warning "Test name does not contain a ':' character. Please use the format 'TestId: TestTitle' → $name"
357	        }
358	        $testResultDetail = $__MtSession.TestResultDetail[$test.ExpandedName]
359	
360	        # Filtered tests never execute Add-MtTestResultDetail. Resolve their
361	        # authored metadata from the commands in the discovered Pester test so
362	        # reports show the test description instead of raw PowerShell source.
363	        if (-not $testResultDetail -and $test.Result -eq 'NotRun') {
364	            $commandNames = @($test.ScriptBlock.Ast.FindAll({
365	                        param($node)
366	                        $node -is [System.Management.Automation.Language.CommandAst]
367	                    }, $true) |
368	                    ForEach-Object { $_.GetCommandName() } |
369	                    Where-Object { $_ } |
370	                    Select-Object -Unique)
371	            $testMetadata = Get-MtTestResultTemplate -CommandName $commandNames -TestId $testId
372	            $testResultDetail = [PSCustomObject]@{
373	                TestTitle       = $null
374	                TestDescription = if ($testMetadata) { $testMetadata.Description } else { 'This test was not run.' }
375	                TestResult      = 'This test was not run.'
376	                TestSkipped     = $null
377	                SkippedReason   = $null
378	                TestInvestigate = $false
379	                Severity        = $null
380	                Service         = $null
381	            }
382	        }
383	
384	        # Add the other test metadata to the test result
385	        $testSetting = Get-MtMaesterConfigTestSetting -TestId $testId
386	        $severity = $testResultDetail.Severity # Default to the test result severity
387	        if ($testSetting -and [string]::IsNullOrEmpty($testSetting.Severity) -eq $false) {
388	            # Overwrite the settings if it is set in the config
389	            $severity = $testSetting.Severity
390	        }
391	
392	        # Setting Result to Error or Investigate, Overwriting the Skipped state
393	        if ($testResultDetail.TestSkipped -eq 'Error' ) {
394	            $result = 'Error'
395	        } elseif ($testResultDetail.TestInvestigate -eq $true) {
396	            $result = 'Investigate'
397	        } elseif ((
398	                $test -and
399	                $test.ErrorRecord -and
400	                $test.ErrorRecord.Count -gt 0 -and
401	                $test.ErrorRecord[0].CategoryInfo -and
402	                $test.ErrorRecord[0].CategoryInfo.Reason) -and
403	            (@('RuntimeException', 'ParameterBindingValidationException', 'ParameterBindingException', 'HttpRequestException', 'TaskCanceledException') -contains $test.ErrorRecord[0].CategoryInfo.Reason )) {
404	            Write-Verbose "Setting result=Error $($name) because: $($test.ErrorRecord[0].CategoryInfo.Reason)"
405	            $result = 'Error'
406	        } else {
407	            $result = $test.Result
408	        }
409	        # Pester's Inconclusive (Set-ItResult -Inconclusive) is not a Maester result: no count, report or XML
410	        # mapping knows it. It means the test could not decide, which Maester reports as Skipped.
411	        if ($result -eq 'Inconclusive') { $result = 'Skipped' }
412	
413	        $annotation = Get-MtPesterRowAnnotation -Test $test -Id $testId -Result $result -ResultDetail $testResultDetail -RunContext $RunContext
414	        if ($annotation.ResultOverride) { $result = $annotation.ResultOverride }
415	        if ($annotation.IdOverride) { $testId = $annotation.IdOverride }
416	        $origin = if ($RunContext -and $RunContext.FileOrigin -and $test.ScriptBlock.File -and $RunContext.FileOrigin.ContainsKey($test.ScriptBlock.File)) {
417	            $RunContext.FileOrigin[$test.ScriptBlock.File]
418	        } else { [PSCustomObject]@{ Source = $null; Suite = $null } }
419	
420	        $timeSpanFormat = 'hh\:mm\:ss'
421	        # Individual tests usually complete in well under a second, so keep milliseconds
422	        # here. The run-level totals below stay on the coarser format.
423	        $testTimeSpanFormat = 'hh\:mm\:ss\.fff'
424	        $mtTestInfo = [ordered]@{
425	            Index           = $testIndex
426	            Id              = $testId
427	            Title           = $testTitle
428	            Name            = $name
429	            HelpUrl         = $helpUrl
430	            Severity        = $severity
431	            Tag             = @($test.Block.Tag + $test.Tag | Select-Object -Unique)
432	            Result          = $result
433	            ScriptBlock     = $test.ScriptBlock.ToString()
434	            ScriptBlockFile = $test.ScriptBlock.File
435	            ErrorRecord     = $test.ErrorRecord
436	            Block           = $test.Block.ExpandedName
437	            Product         = $null
438	            Duration        = $test.Duration.ToString($testTimeSpanFormat)
439	            ResultDetail    = $testResultDetail
440	            # Additive in result schema 2.1.
441	            Source          = $origin.Source
442	            Suite           = $origin.Suite
443	            Format          = $annotation.Format
444	            ReasonCode      = $annotation.ReasonCode
445	            ReasonDetail    = $annotation.ReasonDetail
446	            ParentId        = $annotation.ParentId
447	            InstanceId      = $annotation.InstanceId
448	            Parameters      = $null
449	            Diagnostics     = @()
450	            Package         = $null
451	        }
452	        # A Pester-format row carries the attribute fields of a native row as null.
453	        foreach ($field in $pesterRowAttributes.Keys) { $mtTestInfo[$field] = $pesterRowAttributes[$field] }
454	        $mtTests += [PSCustomObject]$mtTestInfo
455	    }
456	
457	    # Native rows join the Pester rows, sorted the way 2.x sorts: Passed and Failed first, then the rest, each by name.
458	    if ($NativeRows.Count -gt 0) {
459	        $allRows = @($mtTests) + @($NativeRows)
460	        $active = @($allRows | Where-Object { $_.Result -eq 'Passed' -or $_.Result -eq 'Failed' } | Sort-Object -Property Name)
461	        $inactive = @($allRows | Where-Object { $_.Result -ne 'Passed' -and $_.Result -ne 'Failed' } | Sort-Object -Property Name)
