597	        PassedCount       = $Recount.PassedCount
598	        ErrorCount        = $Recount.ErrorCount
599	        InvestigateCount  = $Recount.InvestigateCount
600	        SkippedCount      = $Recount.SkippedCount
601	        NotRunCount       = $Recount.NotRunCount
602	        TotalCount        = $Recount.TotalCount
603	        ExecutedAt        = GetFormattedDate($PesterResults.ExecutedAt)
604	        TotalDuration     = ($PesterResults.Duration + $NativeDuration).ToString($timeSpanFormat)
605	        UserDuration      = ($PesterResults.UserDuration + $NativeDuration).ToString($timeSpanFormat)
