662	    # This runs before the run writes its own files, so the file at this run's output path, when the caller reuses
663	    # a name such as TestResults-latest, is the previous run and is read like any other.
664	    if ($IncludePrevious.IsPresent -and $OutputFiles -and $OutputFiles.PSObject.Properties['OutputFolder']) {
