681	function New-MtResultConfig {
682	    <#
683	    .SYNOPSIS
684	    Returns the effective run config as recorded in the result, with TestSettings synthesised per test.
685	
686	    .DESCRIPTION
687	    TestSettings holds one row per test in the run: Id, Title, the effective Severity, DefaultSeverity
688	    (the attribute's, for native tests) and any keys the user set (design section 9). This keeps the
689	    report's Config page complete once the module no longer ships a row per test.
690	    #>
691	    [Diagnostics.CodeAnalysis.SuppressMessageAttribute('PSUseShouldProcessForStateChangingFunctions', '', Justification = 'Creates an in-memory object only.')]
692	    [CmdletBinding()]
693	    [OutputType([pscustomobject])]
694	    param(
695	        [Parameter()] [AllowNull()] [object] $RunConfig,
696	        [Parameter()] [AllowEmptyCollection()] [object[]] $Rows = @(),
697	        [Parameter()] [AllowEmptyCollection()] [object[]] $NativeRows = @()
698	    )
699	
700	    if ($null -eq $RunConfig) { return $null }
701	    if ($NativeRows.Count -eq 0) { return $RunConfig }
702	
703	    $copy = [pscustomobject]@{}
704	    foreach ($p in $RunConfig.PSObject.Properties) {
705	        if ($p.Name -in 'TestSettings', 'TestSettingsHash') { continue }
706	        $copy | Add-Member -NotePropertyName $p.Name -NotePropertyValue $p.Value
707	    }
708	    $catalog = @{}
709	    foreach ($t in @(Get-MtTestCatalog)) { if ($t.Id) { $catalog[$t.Id] = $t } }
710	    $settings = foreach ($row in $Rows) {
711	        $entry = [ordered]@{ Id = $row.Id; Title = $row.Title; Severity = $row.Severity }
712	        $default = if ($row.ParentId -and $catalog.ContainsKey($row.ParentId)) { $catalog[$row.ParentId].Severity } elseif ($catalog.ContainsKey($row.Id)) { $catalog[$row.Id].Severity } else { $null }
713	        if ($default) { $entry.DefaultSeverity = $default }
714	        $user = if ($RunConfig.TestSettingsHash -and $RunConfig.TestSettingsHash.ContainsKey($row.Id)) { $RunConfig.TestSettingsHash[$row.Id] } else { $null }
715	        if ($user) {
716	            foreach ($p in $user.PSObject.Properties) { if ($p.Name -notin 'Id', 'Title', 'Severity') { $entry[$p.Name] = $p.Value } }
717	        }
718	        [pscustomobject]$entry
719	    }
720	    $copy | Add-Member -NotePropertyName TestSettings -NotePropertyValue @($settings)
721	    $copy
722	}
