function Get-MtStepCatalog {
    <#
    .SYNOPSIS
    Returns the step catalogue of the defender's path (assets/steps), with the problems found in it. Cached for the
    session.

    .DESCRIPTION
    The catalogue (docs/proposals/defenders-path.md, section 4) is a folder of JSON files: goals.json holds the
    goals, and <product-key>.json the steps of one product. A step is one change an administrator makes or one
    state the tenant must reach. Tests name the steps they verify with the Step attribute; the catalogue holds how
    steps relate (Requires, RequiresOneOf, RecommendedFirst, Conflicts, OnlyWhen), how to switch each on (Rollout),
    the Microsoft Learn pages behind them (Sources) and, for a step that is a state of the tenant, the measure that
    decides whether it is done (Measure: the Key of a measure in the measure registry and a MinimumShare).

    Returns an object with:

    - Steps: a case-sensitive dictionary of step ID to step, in file and catalogue order. Each step has every field
      of the format, lists as arrays and missing fields as empty arrays or $null, plus File.
    - Goals: the goals in catalogue order. Each has Id, Title, Summary, Step and Steps: the goal's step and its
      prerequisites at any depth (through Requires, RequiresOneOf and RecommendedFirst), prerequisites first.
    - Problems: one message for each thing that is wrong, each starting with the file name. The build fails on
      any (Get-MtStepProblem); a run uses what is valid.

    -Path reads another folder, such as a fixture in the unit tests, and is not cached.
    #>
    [CmdletBinding()]
    [OutputType([pscustomobject])]
    param(
        # The catalogue folder. Defaults to the module's assets/steps.
        [Parameter()] [string] $Path
    )

    if (-not $Path -and $script:__MtStepCatalog) { return $script:__MtStepCatalog }
    $folder = if ($Path) { $Path } else { Join-Path $ExecutionContext.SessionState.Module.ModuleBase 'assets/steps' }

    $problems = [System.Collections.Generic.List[string]]::new()
    $steps = [System.Collections.Generic.Dictionary[string, object]]::new([System.StringComparer]::Ordinal)
    $goals = [System.Collections.Generic.List[object]]::new()
    $stepPattern = '^[a-z0-9][a-z0-9-]*\.[a-z0-9][a-z0-9-]*$'
    $linePattern = '^[^\r\n]+$'
    $stepKeys = @('Id', 'Title', 'Summary', 'Requires', 'RequiresOneOf', 'RecommendedFirst', 'Conflicts', 'OnlyWhen', 'Rollout', 'Sources', 'Measure', 'Unchecked')
    $sourceKeys = @('Url', 'Mirror', 'Maintainer', 'Note', 'Reviewed')
    $goalKeys = @('Id', 'Title', 'Summary', 'Step')
    $taxonomy = Get-MtTaxonomy

    # A text field: one line, at most -Max characters. Returns the value, or $null after recording a problem.
    $checkText = {
        param($where, $name, $value, $max, [bool] $required)
        if ($null -eq $value -or ($value -is [string] -and $value -eq '')) {
            if ($required) { $problems.Add("${where}: $name is required.") }
            return $null
        }
        if ($value -isnot [string] -or $value -notmatch $linePattern) { $problems.Add("${where}: $name must be one line of text."); return $null }
        if ($value.Length -gt $max) { $problems.Add("${where}: $name is longer than $max characters.") }
        $value
    }
    # A list of step IDs. Returns the valid IDs.
    $checkIds = {
        param($where, $name, $value)
        if ($null -eq $value) { return , @() }
        $ids = @($value)
        if ($value -is [string]) { $problems.Add("${where}: $name must be a list of step IDs."); return , @() }
        $valid = [System.Collections.Generic.List[string]]::new()
        foreach ($id in $ids) {
            if ($id -isnot [string] -or $id -cnotmatch $stepPattern) { $problems.Add("${where}: $name has '$id', which is not a step ID (<product-key>.<name>)."); continue }
            if ($valid.Contains($id)) { $problems.Add("${where}: $name lists '$id' twice."); continue }
            $valid.Add($id)
        }
        , $valid.ToArray()
    }

    if (-not (Test-Path -LiteralPath $folder -PathType Container)) {
        $problems.Add("$($folder): the step catalogue folder does not exist.")
    }
    $files = @(Get-ChildItem -LiteralPath $folder -Filter '*.json' -File -ErrorAction SilentlyContinue | Where-Object { $_.Name -ne 'steps.schema.json' } | Sort-Object Name)

    foreach ($file in $files) {
        $name = $file.Name
        try {
            $content = Get-Content -LiteralPath $file.FullName -Raw | ConvertFrom-Json -AsHashtable -ErrorAction Stop
        } catch {
            $problems.Add("${name}: the file is not valid JSON: $($_.Exception.Message)")
            continue
        }
        if ($content -isnot [System.Collections.IDictionary]) { $problems.Add("${name}: the file must hold a JSON object."); continue }

        if ($name -eq 'goals.json') {
            foreach ($key in $content.Keys) { if ($key -notin '$schema', 'Goals') { $problems.Add("${name}: unknown key '$key'. goals.json holds only Goals.") } }
            foreach ($g in @($content['Goals'])) {
                if ($g -isnot [System.Collections.IDictionary]) { $problems.Add("${name}: every goal must be an object."); continue }
                foreach ($key in $g.Keys) { if ($key -cnotin $goalKeys) { $problems.Add("${name}: goal '$($g['Id'])' has the unknown key '$key'.") } }
                $id = $g['Id']
                if ($id -isnot [string] -or $id -cnotmatch '^[a-z0-9][a-z0-9-]*$') { $problems.Add("${name}: '$id' is not a goal ID (lowercase kebab-case)."); continue }
                if ($goals | Where-Object { $_.Id -eq $id }) { $problems.Add("${name}: the goal '$id' is listed twice."); continue }
                $where = "$name ($id)"
                $goal = [ordered]@{
                    Id      = $id
                    Title   = & $checkText $where 'Title' $g['Title'] 100 $true
                    Summary = & $checkText $where 'Summary' $g['Summary'] 200 $true
                    Step    = $null
                    Steps   = @()
                }
                if ($g['Step'] -isnot [string] -or $g['Step'] -cnotmatch $stepPattern) { $problems.Add("${where}: Step must name the step that achieves the goal.") }
                else { $goal.Step = $g['Step'] }
                $goals.Add([pscustomobject]$goal)
            }
            continue
        }

        $product = $content['Product']
        $fileProduct = [System.IO.Path]::GetFileNameWithoutExtension($name)
        foreach ($key in $content.Keys) { if ($key -notin '$schema', 'Product', 'Steps') { $problems.Add("${name}: unknown key '$key'. A step file holds Product and Steps.") } }
        if ($product -cne $fileProduct) { $problems.Add("${name}: Product is '$product'. A step file is named after its product, so it must be '$fileProduct'.") }
        if (-not $taxonomy.Lookup.Product.ContainsKey($fileProduct) -or $taxonomy.Lookup.Product[$fileProduct].Key -cne $fileProduct) {
            $problems.Add("${name}: '$fileProduct' is not a product key of the taxonomy registry.")
        }

        foreach ($s in @($content['Steps'])) {
            if ($s -isnot [System.Collections.IDictionary]) { $problems.Add("${name}: every step must be an object."); continue }
            $id = $s['Id']
            if ($id -isnot [string] -or $id -cnotmatch $stepPattern) { $problems.Add("${name}: '$id' is not a step ID (<product-key>.<name>, lowercase)."); continue }
            if ($id.Length -gt 80) { $problems.Add("${name}: the step ID '$id' is longer than 80 characters.") }
            if (-not $id.StartsWith("$fileProduct.", [System.StringComparison]::Ordinal)) { $problems.Add("${name}: the step '$id' must start with '$fileProduct.', the product of its file.") }
            if ($steps.ContainsKey($id)) { $problems.Add("${name}: the step '$id' is also in $($steps[$id].File)."); continue }
            $where = "$name ($id)"
            foreach ($key in $s.Keys) { if ($key -cnotin $stepKeys) { $problems.Add("${where}: unknown key '$key'.") } }

            $oneOf = [System.Collections.Generic.List[object]]::new()
            if ($null -ne $s['RequiresOneOf']) {
                foreach ($group in @($s['RequiresOneOf'])) {
                    $members = & $checkIds $where 'RequiresOneOf' $group
                    if ($group -is [string] -or $members.Count -lt 2) { $problems.Add("${where}: each RequiresOneOf group lists at least two steps."); continue }
                    $oneOf.Add($members)
                }
            }
            $onlyWhen = [System.Collections.Generic.List[string]]::new()
            foreach ($condition in @($s['OnlyWhen'] | Where-Object { $null -ne $_ })) {
                if ($condition -is [string] -and ($condition -ceq 'hybrid-identity' -or $condition -cmatch '^license:[A-Za-z0-9_\-]+(&[A-Za-z0-9_\-]+)*$')) { $onlyWhen.Add($condition) }
                else { $problems.Add("${where}: OnlyWhen has '$condition', which is not a known condition (hybrid-identity, license:<service plan>).") }
            }
            $rollout = @(foreach ($sentence in @($s['Rollout'] | Where-Object { $null -ne $_ })) { & $checkText $where 'Rollout' $sentence 200 $true })

            $sources = [System.Collections.Generic.List[object]]::new()
            foreach ($src in @($s['Sources'] | Where-Object { $null -ne $_ })) {
                if ($src -isnot [System.Collections.IDictionary]) { $problems.Add("${where}: every source must be an object."); continue }
                foreach ($key in $src.Keys) { if ($key -cnotin $sourceKeys) { $problems.Add("${where}: a source has the unknown key '$key'.") } }
                $url = $src['Url']; $maintainer = $src['Maintainer']
                if ([bool]$url -eq [bool]$maintainer) { $problems.Add("${where}: a source has either a Url or a Maintainer."); }
                if ($url -and ($url -isnot [string] -or $url -notmatch '^https://learn\.microsoft\.com/\S+$')) { $problems.Add("${where}: the source '$url' is not a Microsoft Learn URL.") }
                elseif ($url -and $url -match '^https://learn\.microsoft\.com/[a-z]{2}-[a-z]{2}/') { $problems.Add("${where}: the source '$url' has a locale. Leave it out, as the check guides do.") }
                if ($maintainer -and ($maintainer -isnot [string] -or $maintainer -notmatch '^[A-Za-z0-9](?:[A-Za-z0-9]|-(?=[A-Za-z0-9])){0,38}$')) { $problems.Add("${where}: the source maintainer '$maintainer' is not a GitHub handle.") }
                if ($src['Mirror'] -and ($src['Mirror'] -isnot [string] -or $src['Mirror'] -notmatch '^[a-z0-9-]+-docs-mirror$')) { $problems.Add("${where}: the source mirror '$($src['Mirror'])' is not the name of a docs mirror repository.") }
                $reviewed = $src['Reviewed']
                if ($reviewed -is [datetime]) { $reviewed = $reviewed.ToString('yyyy-MM-dd', [System.Globalization.CultureInfo]::InvariantCulture) }
                $date = [datetime]::MinValue
                if ($reviewed -isnot [string] -or -not [datetime]::TryParseExact($reviewed, 'yyyy-MM-dd', [System.Globalization.CultureInfo]::InvariantCulture, [System.Globalization.DateTimeStyles]::None, [ref] $date)) {
                    $problems.Add("${where}: a source needs Reviewed, the date it was last read against the step (yyyy-MM-dd).")
                }
                $sources.Add([pscustomobject][ordered]@{
                        Url        = if ($url) { [string]$url } else { $null }
                        Mirror     = if ($src['Mirror']) { [string]$src['Mirror'] } else { $null }
                        Maintainer = if ($maintainer) { [string]$maintainer } else { $null }
                        Note       = & $checkText $where 'A source''s Note' $src['Note'] 200 $true
                        Reviewed   = $reviewed
                    })
            }
            if ($sources.Count -eq 0) { $problems.Add("${where}: a step needs at least one source.") }

            # Measure: the figure that decides whether a state step is done. Whether its Key is in the measure
            # registry is checked by Get-MtStepProblem.
            $measure = $null
            if ($null -ne $s['Measure']) {
                $m = $s['Measure']
                if ($m -isnot [System.Collections.IDictionary]) {
                    $problems.Add("${where}: Measure must be an object with Key and MinimumShare.")
                } else {
                    foreach ($key in $m.Keys) { if ($key -cnotin 'Key', 'MinimumShare') { $problems.Add("${where}: Measure has the unknown key '$key'.") } }
                    $measureKey = $m['Key']
                    $minimum = $m['MinimumShare']
                    $validKey = $measureKey -is [string] -and $measureKey -cmatch '^[a-z0-9][a-z0-9-]*$'
                    $validMinimum = ($minimum -is [int] -or $minimum -is [long]) -and $minimum -ge 1 -and $minimum -le 100
                    if (-not $validKey) { $problems.Add("${where}: Measure's Key '$measureKey' is not a measure key (lowercase kebab-case).") }
                    if (-not $validMinimum) { $problems.Add("${where}: Measure's MinimumShare must be a whole number from 1 to 100.") }
                    if ($validKey -and $validMinimum) { $measure = [pscustomobject][ordered]@{ Key = $measureKey; MinimumShare = [int]$minimum } }
                }
                if ($s['Unchecked']) { $problems.Add("${where}: the step has a Measure, so it must not have Unchecked.") }
            }

            $steps[$id] = [pscustomobject][ordered]@{
                Id               = $id
                Product          = $fileProduct
                Title            = & $checkText $where 'Title' $s['Title'] 100 $true
                Summary          = & $checkText $where 'Summary' $s['Summary'] 200 $true
                Requires         = & $checkIds $where 'Requires' $s['Requires']
                RequiresOneOf    = $oneOf.ToArray()
                RecommendedFirst = & $checkIds $where 'RecommendedFirst' $s['RecommendedFirst']
                Conflicts        = & $checkIds $where 'Conflicts' $s['Conflicts']
                OnlyWhen         = $onlyWhen.ToArray()
                Rollout          = $rollout
                Sources          = $sources.ToArray()
                Measure          = $measure
                Unchecked        = & $checkText $where 'Unchecked' $s['Unchecked'] 200 $false
                File             = $name
            }
        }
    }

    # References: every step a relationship names exists, no step names itself, and none names a step in two
    # relationships.
    $edges = @{}
    foreach ($step in $steps.Values) {
        $where = "$($step.File) ($($step.Id))"
        $named = @{}
        $relations = [ordered]@{
            Requires         = @($step.Requires)
            RequiresOneOf    = @($step.RequiresOneOf | ForEach-Object { $_ })
            RecommendedFirst = @($step.RecommendedFirst)
            Conflicts        = @($step.Conflicts)
        }
        foreach ($relation in $relations.Keys) {
            foreach ($other in ($relations[$relation] | Select-Object -Unique)) {
                if ($other -ceq $step.Id) { $problems.Add("${where}: $relation names the step itself."); continue }
                if (-not $steps.ContainsKey($other)) { $problems.Add("${where}: $relation names '$other', which is not in the catalogue."); continue }
                if ($named.ContainsKey($other) -and $named[$other] -ne $relation) { $problems.Add("${where}: '$other' is in both $($named[$other]) and $relation.") }
                $named[$other] = $relation
            }
        }
        # Order edges: the step comes after these.
        $edges[$step.Id] = @(@($relations.Requires) + @($relations.RequiresOneOf) + @($relations.RecommendedFirst) | Where-Object { $_ -cne $step.Id -and $steps.ContainsKey($_) } | Select-Object -Unique)
    }

    # Cycles through Requires, RequiresOneOf and RecommendedFirst. Each cycle is reported once, from its first step
    # in catalogue order.
    $state = @{}
    $reported = [System.Collections.Generic.HashSet[string]]::new([System.StringComparer]::Ordinal)
    $visit = $null
    $visit = {
        param($id, [System.Collections.Generic.List[string]] $trail)
        $state[$id] = 'Visiting'
        $trail.Add($id)
        foreach ($next in $edges[$id]) {
            if ($state[$next] -eq 'Visiting') {
                $cycle = @($trail.GetRange($trail.IndexOf($next), $trail.Count - $trail.IndexOf($next))) + $next
                $key = (@($cycle | Select-Object -SkipLast 1 | Sort-Object) -join ' ')
                if ($reported.Add($key)) { $problems.Add("$($steps[$next].File) ($next): the steps depend on each other in a cycle: $($cycle -join ' -> ').") }
            } elseif (-not $state[$next]) {
                & $visit $next $trail
            }
        }
        $trail.RemoveAt($trail.Count - 1)
        $state[$id] = 'Done'
    }
    foreach ($id in @($steps.Keys)) { if (-not $state[$id]) { & $visit $id ([System.Collections.Generic.List[string]]::new()) } }

    # A goal's steps: its step and every prerequisite at any depth, prerequisites first. The walk stops at a step
    # it has seen, so a cycle (already reported) does not loop.
    $inGoal = [System.Collections.Generic.HashSet[string]]::new([System.StringComparer]::Ordinal)
    foreach ($goal in $goals) {
        if (-not $goal.Step) { continue }
        if (-not $steps.ContainsKey($goal.Step)) { $problems.Add("goals.json ($($goal.Id)): Step names '$($goal.Step)', which is not in the catalogue."); continue }
        $order = [System.Collections.Generic.List[string]]::new()
        $seen = [System.Collections.Generic.HashSet[string]]::new([System.StringComparer]::Ordinal)
        $walk = $null
        $walk = {
            param($id)
            if (-not $seen.Add($id)) { return }
            foreach ($next in $edges[$id]) { & $walk $next }
            $order.Add($id)
        }
        & $walk $goal.Step
        $goal.Steps = $order.ToArray()
        foreach ($id in $order) { $null = $inGoal.Add($id) }
    }
    foreach ($step in $steps.Values) {
        if (-not $inGoal.Contains($step.Id)) { $problems.Add("$($step.File) ($($step.Id)): the step belongs to no goal. Make it a goal's step or a prerequisite of one.") }
    }
    if ($files.Count -gt 0 -and -not ($files | Where-Object Name -EQ 'goals.json')) { $problems.Add("goals.json: the catalogue has no goals file.") }

    $catalog = [pscustomobject]@{
        Path     = $folder
        Steps    = $steps
        Goals    = $goals.ToArray()
        Problems = $problems.ToArray()
    }
    if (-not $Path) { $script:__MtStepCatalog = $catalog }
    $catalog
}
function Get-MtMeasureRegistry {
    <#
    .SYNOPSIS
    Returns the measure registry of the defender's path (assets/MaesterMeasures.psd1), with the problems found in
    it. Cached for the session.

    .DESCRIPTION
    A measure is a figure the engine reads from Graph for a step that is a state of the tenant
    (docs/proposals/defenders-path.md, section 11). Steps name a measure by its Key in the step catalogue.

    Returns an object with Measures, a case-sensitive dictionary of key to entry (Key, Function, Title, Unit, Caveat,
    Service, License, Permission, each list as an array, Caveat empty when the entry has none), and Problems, one
    message for each entry that is wrong. Whether the reader function exists is checked by Get-MtStepProblem, which
    runs in the module.

    -Path reads another file, such as a fixture in the unit tests, and is not cached.
    #>
    [CmdletBinding()]
    [OutputType([pscustomobject])]
    param(
        # The registry file. Defaults to the module's assets/MaesterMeasures.psd1.
        [Parameter()] [string] $Path
    )

    if (-not $Path -and $script:__MtMeasureRegistry) { return $script:__MtMeasureRegistry }
    $file = if ($Path) { $Path } else { Join-Path $ExecutionContext.SessionState.Module.ModuleBase 'assets/MaesterMeasures.psd1' }
    $name = [System.IO.Path]::GetFileName($file)

    $problems = [System.Collections.Generic.List[string]]::new()
    $measures = [System.Collections.Generic.Dictionary[string, object]]::new([System.StringComparer]::Ordinal)
    $schema = Get-MtTestSchema
    $services = Get-MtServiceRegistry
    $keys = @('Key', 'Function', 'Title', 'Unit', 'Caveat', 'Service', 'License', 'Permission')

    $data = $null
    try { $data = Import-PowerShellDataFile -LiteralPath $file -ErrorAction Stop }
    catch { $problems.Add("${name}: the file can't be read: $($_.Exception.Message)") }

    foreach ($entry in @($data.Measures | Where-Object { $null -ne $_ })) {
        if ($entry -isnot [hashtable]) { $problems.Add("${name}: every measure must be a hashtable."); continue }
        $key = $entry['Key']
        if ($key -isnot [string] -or $key -cnotmatch '^[a-z0-9][a-z0-9-]*$') { $problems.Add("${name}: '$key' is not a measure key (lowercase kebab-case)."); continue }
        if ($measures.ContainsKey($key)) { $problems.Add("${name}: the measure '$key' is listed twice."); continue }
        $where = "$name ($key)"
        foreach ($k in $entry.Keys) { if ($k -cnotin $keys) { $problems.Add("${where}: unknown key '$k'.") } }
        if ($entry['Function'] -isnot [string] -or $entry['Function'] -cnotmatch '^[A-Z][a-z]+-Mt[A-Za-z0-9]+$') { $problems.Add("${where}: Function must name a Maester function, Verb-MtNoun.") }
        foreach ($text in 'Title', 'Unit') {
            if ($entry[$text] -isnot [string] -or $entry[$text] -notmatch '^[^\r\n]+$') { $problems.Add("${where}: $text must be one line of text.") }
        }
        if ($entry.ContainsKey('Caveat') -and ($entry['Caveat'] -isnot [string] -or $entry['Caveat'] -notmatch '^[^\r\n]{1,200}$')) {
            $problems.Add("${where}: Caveat must be one line of 200 characters or less.")
        }
        $service = @($entry['Service'] | Where-Object { $_ })
        if ($service.Count -eq 0) { $problems.Add("${where}: Service is required.") }
        foreach ($s in $service) {
            if (-not (Resolve-MtServiceName -Name ([string]$s) -Registry $services)) { $problems.Add("${where}: Service '$s' is not in the service registry.") }
        }
        foreach ($l in @($entry['License'] | Where-Object { $_ })) {
            if ([string]$l -notmatch $schema.Properties.License.Pattern) { $problems.Add("${where}: License '$l' is not valid.") }
        }
        foreach ($p in @($entry['Permission'] | Where-Object { $_ })) {
            if ([string]$p -notmatch $schema.Properties.Permission.Pattern) { $problems.Add("${where}: Permission '$p' is not valid. Write <Service>:<Kind>:<Name>.") }
        }
        $measures[$key] = [pscustomobject][ordered]@{
            Key        = $key
            Function   = [string]$entry['Function']
            Title      = [string]$entry['Title']
            Unit       = [string]$entry['Unit']
            Caveat     = if ($entry['Caveat'] -is [string]) { $entry['Caveat'] } else { '' }
            Service    = [string[]]@($service)
            License    = [string[]]@($entry['License'] | Where-Object { $_ })
            Permission = [string[]]@($entry['Permission'] | Where-Object { $_ })
        }
    }

    $registry = [pscustomobject]@{
        Path     = $file
        Measures = $measures
        Problems = $problems.ToArray()
    }
    if (-not $Path) { $script:__MtMeasureRegistry = $registry }
    $registry
}
# The measure registry of the defender's path (docs/proposals/defenders-path.md, section 11).
#
# A measure is a figure the engine reads from Graph for a step that is a state of the tenant, such as the share of
# devices that sign in and are compliant. A step names a measure in the step catalogue
# (powershell/assets/steps/<product>.json) as "Measure": { "Key": "<key>", "MinimumShare": <1 to 100> }, and the step
# is done when the figure meets its threshold. A measure is not a test: it has no ID, no result row and no place in
# pass rates.
#
# Keys of each entry:
#   Key         lowercase kebab-case, the name a step's Measure uses
#   Function    the internal reader in powershell/internal/services/<service>/. It reads through the Graph cache and
#               returns Count (objects that meet the bar), Total and Objects (those that fall short, as Type, Id and
#               DisplayName)
#   Title       one line, shown with the figure, for example 'Devices that sign in are compliant'
#   Unit        what is counted, plural, for example 'devices'
#   Caveat      one line of 200 characters or less, shown with the figure, on what it can't see or leaves out
#               (optional)
#   Service     services that must all be connected, as in a test's Service attribute
#   License     service plans, any one of which is enough, as in a test's License attribute (optional)
#   Permission  permissions the reader needs, as in a test's Permission attribute (optional)
@{
    Measures = @(
        @{
            # Step intune.devices-compliant. isCompliant is set by Intune, also for the devices of a compliance partner,
            # which needs Intune licences as well, so a tenant without Intune has no figure to read.
            Key        = 'devices-compliant'
            Function   = 'Get-MtDeviceComplianceShare'
            Title      = 'Devices that sign in are compliant'
            Unit       = 'devices'
            Caveat     = "Devices that aren't registered or joined in Microsoft Entra ID can't be counted. A compliant-device policy blocks them too."
            Service    = 'Graph'
            License    = 'INTUNE_A'
            Permission = 'Graph:Scope:Device.Read.All | Graph:Scope:Directory.Read.All'
        }
        @{
            # Step entra.mfa-registered. isMfaCapable, not isMfaRegistered: the method must also be one the
            # authentication methods policy allows, or the user still can't complete MFA. The registration report needs
            # Microsoft Entra ID P1 and AuditLog.Read.All.
            Key        = 'mfa-capable'
            Function   = 'Get-MtMfaCapableShare'
            Title      = 'Enabled member users can complete MFA'
            Unit       = 'users'
            Caveat     = 'Counts only methods the authentication methods policy allows. Guests, disabled users, emergency access and directory sync accounts are left out.'
            Service    = 'Graph'
            License    = 'AAD_PREMIUM'
            Permission = ('Graph:Scope:AuditLog.Read.All', 'Graph:Scope:Directory.Read.All')
        }
    )
}

function Resolve-MtNativePlan {
    <#
    .SYNOPSIS
    Decides, for every native test, whether it runs and if not why (design stages 5 and 6).

    .DESCRIPTION
    Gates apply in this order, and the first failing gate gives the reason (design section 6):
    invalid metadata; disabled by config; selection (IDs, excluded products, typed selectors, tags, opt-in
    service, Preview, long-running); platform; tenant type; cloud; service; licence; parameter binding.

    The default exclusions are decided by attribute, not by tag (test attribute design, section 4): a test
    with Lifecycle = 'Preview' or LongRunning is left out when the run excludes them by default
    (-AutoExcludedTag) and the test is not named by its exact ID, and a test whose service is opt-in, such
    as Active Directory, when that service is not connected.

    Each plan row has: Test, Disposition (Run, NotRun, Skipped or Error), ReasonCode, ReasonDetail,
    LegacySkipCode, Parameters (the bound hashtable), EffectiveParameters, TimeoutSeconds, Setting (the
    TestSettings row), InstancePatterns (for a family selected by instance ID) and ExactlyNamed.
    #>
    [CmdletBinding()]
    [OutputType([pscustomobject])]
    param(
        [Parameter(Mandatory)] [AllowEmptyCollection()] [object[]] $Test,
        [Parameter(Mandatory)] [pscustomobject] $Selection,
        [Parameter(Mandatory)] [pscustomobject] $RunConfig,
        [Parameter()] [AllowNull()] [pscustomobject] $TenantContext,
        # The include and exclude tags of the run, and which exclusions the engine added by default
        # (Preview, LongRunning, AD). The defaults are applied to native tests by attribute.
        [Parameter()] [string[]] $IncludeTag = @(),
        [Parameter()] [string[]] $ExcludeTag = @(),
        [Parameter()] [string[]] $AutoExcludedTag = @(),
        # Parameter values that win over the config (Invoke-MtTest -Parameter), by test ID.
        [Parameter()] [hashtable] $ParameterOverride = @{},
        [Parameter()] [switch] $DryRun
    )

    $environment = if ($RunConfig.PSObject.Properties['Environment']) { $RunConfig.Environment } else { $null }
    $enforce = @{ Service = $true; License = $true; TenantType = $false; Cloud = $false }
    if ($environment -and $environment.PSObject.Properties['Enforce'] -and $environment.Enforce) {
        foreach ($p in $environment.Enforce.PSObject.Properties) { if ($enforce.ContainsKey($p.Name)) { $enforce[$p.Name] = [bool]$p.Value } }
    }
    $execution = if ($RunConfig.PSObject.Properties['Execution']) { $RunConfig.Execution } else { $null }
    $registry = Get-MtServiceRegistry
    # Allow-list mode needs the rows that enable a test. Read them once, not once per test: a config copied
    # from 2.x has hundreds of rows.
    $allowListIds = [System.Collections.Generic.HashSet[string]]::new([System.StringComparer]::OrdinalIgnoreCase)
    if ($Selection.DefaultAction -eq 'Skip') {
        foreach ($ts in @($RunConfig.TestSettings)) {
            if ($ts -and $ts.Id -and $ts.PSObject.Properties['Enabled'] -and $ts.Enabled -eq $true) { $null = $allowListIds.Add([string]$ts.Id) }
        }
    }

    $selectorInUse = Test-MtSelectorInUse -Selection $Selection
    $userExcludeTag = @($ExcludeTag | Where-Object { $_ -and $_ -notin $AutoExcludedTag })
    # How a tag pattern matches a test: by one of its own tags, else by a Maester 2.x tag, else not at all.
    $matchTag = {
        param($tags, $pattern)
        foreach ($tag in $tags.Own) { if ($tag -like $pattern) { return 'Own' } }
        foreach ($tag in $tags.Legacy) { if ($tag -like $pattern) { return 'Legacy' } }
    }
    $legacyTagUsed = [ordered]@{}

    foreach ($t in $Test) {
        $row = [ordered]@{
            Test                = $t
            Disposition         = 'Run'
            ReasonCode          = $null
            ReasonDetail        = $null
            LegacySkipCode      = $null
            Parameters          = @{}
            EffectiveParameters = @()
            TimeoutSeconds      = 0
            Setting             = $null
            InstancePatterns    = @()
            ExactlyNamed        = $false
        }
        $set = { param($disposition, $code, $detail, $legacy) $row.Disposition = $disposition; $row.ReasonCode = $code; $row.ReasonDetail = $detail; $row.LegacySkipCode = $legacy }

        # A test of a pack that did not pass the loader gate: reported, never run (Maester Packs design, section 5.5).
        if ($t.PSObject.Properties['PackStatus'] -and $t.PackStatus) {
            & $set $t.PackStatus.Disposition $t.PackStatus.ReasonCode $t.PackStatus.Reason $(if ($t.PackStatus.Disposition -eq 'NotRun') { 'Custom' })
            [pscustomobject]$row; continue
        }

        # Invalid metadata, load failures, duplicates, newer engine required.
        if ($t.Errors -and $t.Errors.Count -gt 0) {
            $first = $t.Errors[0]
            $location = if ($t.File) { " ($([System.IO.Path]::GetFileName($t.File)), line $($first.Line))" } else { '' }
            & $set 'Error' $first.Code "$($first.Message)$location"
            [pscustomobject]$row; continue
        }

        $isFamily = [bool]$t.InstanceSource
        $setting = Get-MtTestSetting -RunConfig $RunConfig -Id $t.Id
        $row.Setting = $setting

        # Config admission.
        if ($setting -and $setting.PSObject.Properties['Enabled'] -and $setting.Enabled -eq $false) {
            & $set 'NotRun' 'DisabledByConfig' $(if ($setting.PSObject.Properties['Reason'] -and $setting.Reason) { [string]$setting.Reason } else { 'Disabled in the Maester config.' })
            [pscustomobject]$row; continue
        }
        # A family is also admitted by a row for one of its instances.
        if ($Selection.DefaultAction -eq 'Skip' -and -not ($allowListIds.Contains([string]$t.Id) -or ($isFamily -and ($allowListIds | Where-Object { $_ -like "$($t.Id).*" })))) {
            & $set 'NotRun' 'NotListed' 'Selection.DefaultAction is Skip and no TestSettings row enables this test.'
            [pscustomobject]$row; continue
        }

        # Selection by ID.
        $excludedBy = @(Test-MtIdMatch -Id $t.Id -Pattern $Selection.ExcludeTestId)
        if (-not $excludedBy -and $isFamily) { $excludedBy = @($Selection.ExcludeTestId | Where-Object { $_.Contains('*') -and "$($t.Id).*" -like $_ }) }
        if ($excludedBy) {
            & $set 'NotRun' 'ExcludedById' "Excluded by ID ($($excludedBy -join ', '))."
            [pscustomobject]$row; continue
        }
        # -ExcludeProduct matches Product or RelatedProduct, and wins over -TestId and -Product.
        $excludedBy = @(Test-MtProductExcluded -Selection $Selection -Product (@($t.Product) + @($t.RelatedProduct)))
        if ($excludedBy) {
            & $set 'NotRun' 'ExcludedByProduct' "Excluded by product ($($excludedBy -join ', '))."
            [pscustomobject]$row; continue
        }
        if ($Selection.TestId.Count -gt 0) {
            $includedBy = @(Test-MtIdMatch -Id $t.Id -Pattern $Selection.TestId)
            if (-not $includedBy -and $isFamily) {
                $instancePatterns = @($Selection.TestId | Where-Object { $_ -like "$($t.Id).*" -and -not ($_.Contains('*') -and "$($t.Id).*" -like $_) })
                $wholeFamily = @($Selection.TestId | Where-Object { $_.Contains('*') -and "$($t.Id).*" -like $_ })
                $includedBy = @($wholeFamily) + @($instancePatterns)
                if (-not $wholeFamily) { $row.InstancePatterns = $instancePatterns }
            }
            if (-not $includedBy) {
                & $set 'NotRun' 'NotSelected' 'Not in the list of test IDs to run.'
                [pscustomobject]$row; continue
            }
            $row.ExactlyNamed = [bool]($includedBy | Where-Object { -not $_.Contains('*') })
        }

        # Typed selectors: Product (or RelatedProduct), Feature, Area, the effective severity and Suite.
        if ($selectorInUse) {
            $severity = if ($setting -and $setting.PSObject.Properties['Severity'] -and $setting.Severity) { [string]$setting.Severity } else { [string]$t.Severity }
            $miss = Test-MtSelectorMatch -Selection $Selection -Product (@($t.Product) + @($t.RelatedProduct)) -Feature $t.Feature -Area $t.Area -Severity $severity -Suite $t.Suite
            if ($miss) {
                & $set 'NotRun' 'NotSelected' "Not selected by -$($miss.Selector) ($($miss.Value -join ', '))."
                [pscustomobject]$row; continue
            }
            # A pack's suite named exactly by -Suite turns the pack on, as an exact ID does: its preview and
            # long-running tests run too (Maester Packs design, section 4.7).
            if ($t.PSObject.Properties['PackId'] -and $t.PackId -and ($Selection.Suite | Where-Object { -not $_.Contains('*') -and $_ -eq $t.Suite })) { $row.ExactlyNamed = $true }
        }

        # A pack named with -Pack (or Selection.Pack) runs whole, as an exact ID does: its preview and
        # long-running tests run too.
        if ($t.PSObject.Properties['PackSelected'] -and $t.PackSelected) { $row.ExactlyNamed = $true }

        # Selection by tag: the tags of the test and its suite and, for a built-in test, its ID and its
        # Maester 2.x tags (section 5.1). A pattern that only a 2.x tag answers is noted for the warning below.
        $tags = if ($IncludeTag.Count -gt 0 -or $userExcludeTag.Count -gt 0) { Get-MtSelectionTag -Test $t } else { $null }
        $included = $IncludeTag.Count -eq 0
        if (-not $included) {
            foreach ($pattern in $IncludeTag) {
                $via = & $matchTag $tags $pattern
                if (-not $via) { continue }
                if ($via -eq 'Legacy') { $legacyTagUsed[$pattern] = 'Include' }
                $included = $true
                break
            }
        }
        if (-not $included) {
            & $set 'NotRun' 'NotSelected' "Matched none of the tags $($IncludeTag -join ', ')."
            [pscustomobject]$row; continue
        }

        # Default exclusions, by attribute. An opt-in service that is not connected comes first.
        $optIn = @($t.Service | Where-Object { $registry.Services[$_].OptIn })
        $optInDisconnected = @($optIn | Where-Object { $TenantContext -and $TenantContext.Services.PSObject.Properties[$_] -and -not $TenantContext.Services.$_ })
        if ($optInDisconnected) {
            $first = $optInDisconnected[0]
            $name = if ($registry.Services[$first].ContainsKey('DisplayName')) { $registry.Services[$first].DisplayName } else { 'Active Directory' }
            & $set 'NotRun' 'OptInServiceNotConnected' "$name tests run only after Connect-Maester -Service $first."
            [pscustomobject]$row; continue
        }
        # A test named by its exact ID runs even if it is a preview or long-running test.
        if (-not $row.ExactlyNamed) {
            if ($t.Lifecycle -eq 'Preview' -and $AutoExcludedTag -contains 'Preview') {
                & $set 'NotRun' 'Preview' 'Preview test. Use -IncludePreview to run it.'
                [pscustomobject]$row; continue
            }
            if ($t.LongRunning -and $AutoExcludedTag -contains 'LongRunning') {
                & $set 'NotRun' 'LongRunning' 'Long-running test. Use -IncludeLongRunning to run it.'
                [pscustomobject]$row; continue
            }
        }
        # The tags the caller excludes. The tags the engine adds for Pester-format tests are not among them.
        $hits = @(foreach ($pattern in $userExcludeTag) {
                $via = & $matchTag $tags $pattern
                if (-not $via) { continue }
                if ($via -eq 'Legacy' -and -not $legacyTagUsed.Contains($pattern)) { $legacyTagUsed[$pattern] = 'Exclude' }
                $pattern
            })
        if ($hits) {
            & $set 'NotRun' 'ExcludedByTag' "Excluded by tag ($(@($hits | Select-Object -Unique) -join ', '))."
            [pscustomobject]$row; continue
        }

        # Applicability.
        $gate = Test-MtApplicability -Test $t -TenantContext $TenantContext -Enforce $enforce
        if ($gate) {
            & $set 'Skipped' $gate.ReasonCode $gate.ReasonDetail $gate.LegacySkipCode
            [pscustomobject]$row; continue
        }

        # Parameter binding.
        $values = if ($setting -and $setting.PSObject.Properties['Parameters']) { $setting.Parameters } else { $null }
        $override = if ($ParameterOverride.ContainsKey($t.Id)) { $ParameterOverride[$t.Id] } else { $null }
        $binding = ConvertTo-MtTestParameter -Test $t -ConfigValue $values -Override $override
        $row.EffectiveParameters = $binding.Effective
        if ($binding.Error) {
            & $set 'Error' 'InvalidConfiguration' $binding.Error
            [pscustomobject]$row; continue
        }
        $row.Parameters = $binding.Bound

        # Timeout: the test's row, then the long-running default, then the run default. 0 means none.
        $timeout = 0
        if ($execution -and $execution.PSObject.Properties['TestTimeoutSeconds'] -and $execution.TestTimeoutSeconds) { $timeout = [int]$execution.TestTimeoutSeconds }
        # A more specific value set to 0 turns off a broader timeout, so presence (not truthiness) decides.
        if ($t.LongRunning -and $execution -and $execution.PSObject.Properties['LongRunningTimeoutSeconds'] -and $null -ne $execution.LongRunningTimeoutSeconds) { $timeout = [int]$execution.LongRunningTimeoutSeconds }
        if ($setting -and $setting.PSObject.Properties['TimeoutSeconds'] -and $null -ne $setting.TimeoutSeconds) { $timeout = [int]$setting.TimeoutSeconds }
        $row.TimeoutSeconds = $timeout

        if ($DryRun) { & $set 'NotRun' 'DryRun' 'Dry run: this test would have run.' }
        [pscustomobject]$row
    }

    # One warning per run when a tag of Maester 2.x did the selecting, with the typed selector that replaces it.
    if ($legacyTagUsed.Count -gt 0) { Write-Warning (Get-MtLegacyTagWarning -Tag @($legacyTagUsed.Keys) -ExcludeTag @($legacyTagUsed.Keys | Where-Object { $legacyTagUsed[$_] -eq 'Exclude' })) }
}

function Get-MtLegacyTagWarning {
    <#
    .SYNOPSIS
    Returns the text of the warning for a run that selected tests through Maester 2.x tags.

    .DESCRIPTION
    Names each tag and, where assets/Maester.LegacyTags.json gives one, the typed selector that replaces
    it, for example -Tag CA and -Feature conditional-access (test attribute design, section 5.1). A product
    tag used in -ExcludeTag names -ExcludeProduct: -ExcludeTag EXO is now -ExcludeProduct exchange.
    #>
    [CmdletBinding()]
    [OutputType([string])]
    param(
        # The -Tag and -ExcludeTag values that matched a test only through a 2.x tag.
        [Parameter(Mandatory)] [string[]] $Tag,
        # Those of the tags that matched a test only through -ExcludeTag.
        [Parameter()] [AllowEmptyCollection()] [string[]] $ExcludeTag = @()
    )

    $table = Get-MtLegacyTagTable
    $named = foreach ($t in $Tag) {
        $replacement = $null
        if ($table.Replacement.TryGetValue($t, [ref] $replacement)) {
            if ($t -in $ExcludeTag -and $replacement -like '-Product *') { $replacement = $replacement -replace '^-Product ', '-ExcludeProduct ' }
            "'$t' (now $replacement)"
        } else { "'$t'" }
    }
    if (@($named).Count -eq 1) {
        "The tag $named is a Maester 2.x tag. It still selects the same built-in tests, but tests added after Maester 3.0 do not carry it."
    } else {
        "These tags are Maester 2.x tags: $($named -join ', '). They still select the same built-in tests, but tests added after Maester 3.0 do not carry them."
    }
}

function Get-MtTestSetting {
    <#
    .SYNOPSIS
    Returns the TestSettings row for a test ID (case-insensitive), or for a family instance its parent's.
    #>
    [CmdletBinding()]
    [OutputType([pscustomobject])]
    param(
        [Parameter(Mandatory)] [pscustomobject] $RunConfig,
        [Parameter(Mandatory)] [string] $Id,
        [Parameter()] [string] $ParentId
    )
    $hash = $RunConfig.TestSettingsHash
    if ($hash -and $hash.ContainsKey($Id)) { return $hash[$Id] }
    if ($ParentId -and $hash -and $hash.ContainsKey($ParentId)) { return $hash[$ParentId] }
    $null
}

function Test-MtApplicability {
    <#
    .SYNOPSIS
    Checks platform, tenant type, cloud, service and licence. Returns the first failing gate, or $null.
    #>
    [CmdletBinding()]
    [OutputType([pscustomobject])]
    param(
        [Parameter(Mandatory)] [object] $Test,
        [Parameter()] [AllowNull()] [pscustomobject] $TenantContext,
        [Parameter(Mandatory)] [hashtable] $Enforce
    )

    $fail = { param($code, $detail, $legacy) [pscustomobject]@{ ReasonCode = $code; ReasonDetail = $detail; LegacySkipCode = $legacy } }
    $platform = if ($TenantContext) { $TenantContext.Platform } elseif ($IsWindows) { 'Windows' } elseif ($IsMacOS) { 'MacOS' } else { 'Linux' }
    if (@($Test.Platform).Count -gt 0 -and $platform -notin $Test.Platform) {
        return & $fail 'PlatformMismatch' "This test runs only on $($Test.Platform -join ', '); this computer runs $platform." 'NotSupported'
    }
    if (-not $TenantContext) { return $null }

    $tenantTypes = if (@($Test.TenantType).Count -gt 0) { @($Test.TenantType) } else { @('Workforce') }
    if ($Enforce.TenantType -and $TenantContext.TenantType -ne 'Unknown' -and $TenantContext.TenantType -notin $tenantTypes) {
        return & $fail 'TenantTypeMismatch' "This test applies to $($tenantTypes -join ', ') tenants; this tenant is $($TenantContext.TenantType)." 'NotSupported'
    }
    if ($Enforce.Cloud -and @($Test.Cloud).Count -gt 0 -and $TenantContext.Cloud -ne 'Unknown' -and $TenantContext.Cloud -notin $Test.Cloud) {
        return & $fail 'CloudMismatch' "This test applies to $($Test.Cloud -join ', '); this tenant is in $($TenantContext.Cloud)." 'NotSupported'
    }

    if ($Enforce.Service) {
        if (@($Test.UnregisteredServices).Count -gt 0) {
            return & $fail 'ServiceNotRegistered' "The service $($Test.UnregisteredServices -join ', ') is not known to this version of Maester." 'NotSupported'
        }
        $registry = Get-MtServiceRegistry
        foreach ($s in @($Test.Service)) {
            $connected = $TenantContext.Services.PSObject.Properties[$s]
            if ($connected -and -not $connected.Value) {
                $entry = $registry.Services[$s]
                $legacy = $entry.LegacySkipCode
                # A pack connector's service names its own connect command.
                $text = if ($entry.ContainsKey('Pack')) { "Not connected to $($entry.DisplayName). Run Connect-Maester -Service $s." } else { Get-MtSkippedReason -SkippedBecause $legacy }
                return & $fail 'ServiceNotConnected' $text $legacy
            }
        }
    }

    if ($Enforce.License -and @($Test.License).Count -gt 0 -and $TenantContext.Licenses.State -eq 'Known') {
        if (-not (Test-MtLicenseRequirement -Requirement $Test.License -Licenses $TenantContext.Licenses)) {
            $table = Get-MtLicenseTable
            $firstToken = REDACTED -split '&')[0]
            $legacy = if ($table.Tokens.ContainsKey($firstToken)) { $table.Tokens[$firstToken].LegacySkipCode } else { 'Custom' }
            $detail = "This test requires one of these licences: $($Test.License -join ', ')."
            return & $fail 'LicenseNotFound' $detail $legacy
        }
    }
    $null
}

function Test-MtLicenseRequirement {
    <#
    .SYNOPSIS
    True when the tenant has any one element of a License list; 'A&B' inside an element means all of them.
    #>
    [CmdletBinding()]
    [OutputType([bool])]
    param(
        [Parameter(Mandatory)] [string[]] $Requirement,
        [Parameter(Mandatory)] [object] $Licenses
    )

    $table = Get-MtLicenseTable
    $planNames = @($Licenses.ServicePlanNames)
    $planIds = @($Licenses.ServicePlanIds)
    $skuIds = @($Licenses.SkuIds)
    foreach ($element in $Requirement) {
        $all = $true
        foreach ($token in ($element -split '&' | ForEach-Object { $_.Trim() } | Where-Object { $_ })) {
            $entry = $null
            foreach ($key in $table.Tokens.Keys) { if ($key -eq $token) { $entry = $table.Tokens[$key] } }
            $has = if ($entry) {
                [bool](@($entry.ServicePlanIds) | Where-Object { $_ -in $planIds }) -or [bool](@($entry.SkuIds) | Where-Object { $_ -in $skuIds }) -or ($planNames -contains $token)
            } else {
                $planNames -contains $token
            }
            if (-not $has) { $all = $false; break }
        }
        if ($all) { return $true }
    }
    $false
}

