function Resolve-MtSelection {
    <#
    .SYNOPSIS
    Combines the run config's Selection section with the Invoke-Maester parameters (design section 7.3).

    .DESCRIPTION
    -Tag, -TestId and the typed selectors (-Product, -Feature, -Area, -Severity, -Suite) replace the config
    lists, and so does -Pack; -ExcludeTag, -ExcludeTestId and -ExcludeProduct add to them; the include switches are true
    when either source sets them. A product named by an alias, such as Entra ID, becomes its key, in -Product and
    -ExcludeProduct alike.

    .EXAMPLE
    Resolve-MtSelection -RunConfig $config -BoundParameters $PSBoundParameters
    #>
    [CmdletBinding()]
    [OutputType([pscustomobject])]
    param(
        [Parameter(Mandatory)]
        [pscustomobject] $RunConfig,

        [Parameter()] [string[]] $Tag,
        [Parameter()] [string[]] $ExcludeTag,
        [Parameter()] [string[]] $TestId,
        [Parameter()] [string[]] $ExcludeTestId,
        [Parameter()] [string[]] $Product,
        [Parameter()] [string[]] $ExcludeProduct,
        [Parameter()] [string[]] $Feature,
        [Parameter()] [string[]] $Area,
        [Parameter()] [string[]] $Severity,
        [Parameter()] [string[]] $Suite,
        [Parameter()] [string[]] $Pack,
        [Parameter()] [switch] $IncludePreview,
        [Parameter()] [switch] $IncludeLongRunning
    )

    $s = $RunConfig.Selection
    # The parameter's values, else the config's, without blanks.
    $selector = {
        param($value, $name)
        $list = if ($value) { $value } elseif ($s.PSObject.Properties[$name]) { $s.$name } else { @() }
        foreach ($item in @($list)) { if (-not [string]::IsNullOrWhiteSpace($item)) { [string]$item } }
    }
    # A product name becomes its key; a wildcard pattern stays as it is.
    $productKey = {
        param($item)
        $key = if ($item.Contains('*')) { $null } else { Resolve-MtProductKey -Name $item }
        if ($key) { $key } else { $item }
    }
    $products = foreach ($item in @(& $selector $Product 'Product')) { & $productKey $item }
    $configExcludeProduct = if ($s.PSObject.Properties['ExcludeProduct']) { @($s.ExcludeProduct) } else { @() }
    $excludeProducts = foreach ($item in @($configExcludeProduct) + @($ExcludeProduct)) {
        if (-not [string]::IsNullOrWhiteSpace($item)) { & $productKey ([string]$item) }
    }
    [pscustomobject]@{
        Tag                = @(if ($Tag) { $Tag } else { $s.Tag })
        ExcludeTag         = @(@($s.ExcludeTag) + @($ExcludeTag) | Where-Object { $_ } | Select-Object -Unique)
        TestId             = @(if ($TestId) { $TestId } else { $s.TestId })
        ExcludeTestId      = @(@($s.ExcludeTestId) + @($ExcludeTestId) | Where-Object { $_ } | Select-Object -Unique)
        Product            = [string[]]@($products)
        ExcludeProduct     = [string[]]@($excludeProducts | Select-Object -Unique)
        Feature            = [string[]]@(& $selector $Feature 'Feature')
        Area               = [string[]]@(& $selector $Area 'Area')
        Severity           = [string[]]@(& $selector $Severity 'Severity')
        Suite              = [string[]]@(& $selector $Suite 'Suite')
        Pack               = [string[]]@(& $selector $Pack 'Pack')
        IncludePreview     = $IncludePreview.IsPresent -or [bool]$s.IncludePreview
        IncludeLongRunning = $IncludeLongRunning.IsPresent -or [bool]$s.IncludeLongRunning
        DefaultAction      = $s.DefaultAction
        OnUnknownId        = $s.OnUnknownId
        BuiltIn            = $s.BuiltIn
    }
}

function Test-MtSelectorMatch {
    <#
    .SYNOPSIS
    Checks a test against the typed selectors of a run and returns the first selector it does not match, or $null.

    .DESCRIPTION
    The typed selectors are Product, Feature, Area, Severity and Suite (test attribute design, section 4).
    The values of one selector are alternatives, with '*' wildcards as for tags; different selectors must
    all match. Product matches the test's Product or any of its RelatedProduct values. A test that has no
    value for a selector in use does not match it, which is how a Pester-format test, which has no Product,
    Feature or Area, is left out of a run that selects by one of them.

    Returns an object with Selector (the name) and Value (the selector's values), or nothing when the test
    matches every selector in use.
    #>
    [CmdletBinding()]
    [OutputType([pscustomobject])]
    param(
        # Output of Resolve-MtSelection.
        [Parameter(Mandatory)] [pscustomobject] $Selection,
        [Parameter()] [AllowNull()] [AllowEmptyCollection()] [string[]] $Product,
        [Parameter()] [AllowNull()] [AllowEmptyString()] [string] $Feature,
        [Parameter()] [AllowNull()] [AllowEmptyString()] [string] $Area,
        [Parameter()] [AllowNull()] [AllowEmptyString()] [string] $Severity,
        [Parameter()] [AllowNull()] [AllowEmptyString()] [string] $Suite
    )

    $values = [ordered]@{ Product = @($Product); Feature = @($Feature); Area = @($Area); Severity = @($Severity); Suite = @($Suite) }
    foreach ($name in $values.Keys) {
        if (-not $Selection.PSObject.Properties[$name]) { continue }
        $patterns = @($Selection.$name | Where-Object { $_ })
        if ($patterns.Count -eq 0) { continue }
        $matched = $false
        foreach ($value in @($values[$name] | Where-Object { $_ })) {
            foreach ($pattern in $patterns) { if ($value -like $pattern) { $matched = $true; break } }
            if ($matched) { break }
        }
        if (-not $matched) { return [pscustomobject]@{ Selector = $name; Value = $patterns } }
    }
}

function Test-MtSelectorInUse {
    <#
    .SYNOPSIS
    True when a run selects by Product, Feature, Area, Severity or Suite.
    #>
    [CmdletBinding()]
    [OutputType([bool])]
    param(
        [Parameter(Mandatory)] [pscustomobject] $Selection
    )
    foreach ($name in 'Product', 'Feature', 'Area', 'Severity', 'Suite') {
        if ($Selection.PSObject.Properties[$name] -and @($Selection.$name | Where-Object { $_ }).Count -gt 0) { return $true }
    }
    $false
}

function Test-MtProductExcluded {
    <#
    .SYNOPSIS
    Returns the -ExcludeProduct patterns that match a test's Product or RelatedProduct values.

    .DESCRIPTION
    The patterns are product keys or '*' wildcards, as for -Product. A test that has no product, such as a
    Pester-format test, matches none: -ExcludeProduct never leaves it out, unlike -Product.
    #>
    [CmdletBinding()]
    [OutputType([string])]
    param(
        # Output of Resolve-MtSelection.
        [Parameter(Mandatory)] [pscustomobject] $Selection,
        # The test's Product and RelatedProduct values.
        [Parameter()] [AllowNull()] [AllowEmptyCollection()] [string[]] $Product
    )

    if (-not $Selection.PSObject.Properties['ExcludeProduct']) { return }
    $values = @($Product | Where-Object { $_ })
    foreach ($pattern in @($Selection.ExcludeProduct | Where-Object { $_ })) {
        if ($values | Where-Object { $_ -like $pattern }) { $pattern }
    }
}

function Test-MtIdMatch {
    <#
    .SYNOPSIS
    Returns the patterns that match an ID: exact or '*' wildcards, case-insensitive.
    #>
    [CmdletBinding()]
    [OutputType([string])]
    param(
        [Parameter(Mandatory)] [AllowEmptyString()] [string] $Id,
        [Parameter()] [string[]] $Pattern = @()
    )

    foreach ($p in $Pattern) {
        if ($p.Contains('*')) {
            if ($Id -like $p) { $p }
        } elseif ($Id -eq $p) {
            $p
        }
    }
}

function Get-MtPesterSelectionPlan {
    <#
    .SYNOPSIS
    Decides which Pester It blocks to exclude by line for ID-based selection and config admission.

    .DESCRIPTION
    Pester selects by tag only. ID-based rules (-TestId, -ExcludeTestId, TestSettings[].Enabled and
    Selection.DefaultAction) and the typed selectors (-Product, -Feature, -Area, -Severity, -Suite) are
    applied by excluding the It lines of the tests they deselect (Filter.ExcludeLine). Excluded tests stay
    in the result as NotRun rows with a reason code. A test whose name is built at run time is matched as a
    family through its literal ID prefix.

    A Pester-format test has no Product, Feature or Area, so a run that selects by one of them leaves it
    out, and -ExcludeProduct never excludes it. Its Suite is that of its file (-FileOrigin), and its severity
    is known before the run only from a TestSettings row.

    Returns: ExcludeLines (file:line strings), Reasons (file:line -> reason object), LiftPreview and
    LiftLongRunning (an exact -TestId names a Preview or long-running test, so the default tag
    exclusion is dropped and other such tests are excluded by line instead), UnknownIds, and the
    inventory it used.
    #>
    [CmdletBinding()]
    [OutputType([pscustomobject])]
    param(

    param(
        # Rows from Get-MtPesterFileInventory.
        [Parameter(Mandatory)]
        [AllowEmptyCollection()]
        [object[]] $Inventory,

        # Output of Resolve-MtSelection.
        [Parameter(Mandatory)]
        [pscustomobject] $Selection,

        # The resolved run config (for TestSettings).
        [Parameter(Mandatory)]
        [pscustomobject] $RunConfig,

        # Source and Suite of each test file, by path (Get-MtTestFileOrigin). Used by the -Suite selector.
        [Parameter()]
        [hashtable] $FileOrigin = @{}
    )

    $reasons = [ordered]@{}
    $liftPreview = $false
    $liftLongRunning = $false
    $knownIds = [System.Collections.Generic.HashSet[string]]::new([System.StringComparer]::OrdinalIgnoreCase)
    $familyParents = [System.Collections.Generic.List[string]]::new()

    $rows = foreach ($row in $Inventory) {
        if ($row.ParseError -or -not $row.Line) { continue }
        $parentId = $null
        if (-not $row.IsStatic) {
            $parentId = Get-MtFamilyParentId -LiteralPrefix $row.LiteralPrefix
            if ($parentId) { $familyParents.Add($parentId) }
        } elseif ($row.Id) {
            $null = $knownIds.Add($row.Id)
        }
        [pscustomobject]@{
            Key      = "$($row.File):$($row.Line)"
            Id       = $row.Id
            ParentId = $parentId
            Tags     = $row.Tags
            Row      = $row
        }
    }

    $enabledRows = @{}
    foreach ($ts in @($RunConfig.TestSettings)) {
        if ($null -ne $ts -and $ts.Id -and $ts.PSObject.Properties['Enabled']) { $enabledRows[[string]$ts.Id] = $ts }
    }

    $selectorInUse = Test-MtSelectorInUse -Selection $Selection
    foreach ($r in $rows) {
        if ($reasons.Contains($r.Key)) { continue }
        # The IDs this row answers to: its own, or for a family its parent and any instance under it.
        $matchId = if ($r.Id) { $r.Id } else { $r.ParentId }
        if (-not $matchId) { continue }

        # Config admission and disabling.
        $setting = $null
        if ($r.Id -and $enabledRows.ContainsKey($r.Id)) { $setting = $enabledRows[$r.Id] }
        elseif ($r.ParentId) {
            # A row that enables the parent or any instance admits the family. Only a row on the parent disables
            # it: a row that disables one instance is applied to that instance after the run (DisabledInstances).
            $setting = $enabledRows.Keys | Where-Object { $_ -eq $r.ParentId -or $_ -like "$($r.ParentId).*" } |
                ForEach-Object { $enabledRows[$_] } | Where-Object { $_.Enabled -eq $true } | Select-Object -First 1
            if (-not $setting -and $enabledRows.ContainsKey($r.ParentId)) { $setting = $enabledRows[$r.ParentId] }
        }
        if ($setting -and $setting.Enabled -eq $false) {
            $reasons[$r.Key] = New-MtSelectionReason -ReasonCode 'DisabledByConfig' -Detail $(if ($setting.Reason) { [string]$setting.Reason } else { 'Disabled in the Maester config.' })
            continue
        }
        if ($Selection.DefaultAction -eq 'Skip' -and -not ($setting -and $setting.Enabled -eq $true)) {
            $reasons[$r.Key] = New-MtSelectionReason -ReasonCode 'NotListed' -Detail 'Selection.DefaultAction is Skip and no TestSettings row enables this test.'
            continue
        }

        # Typed selectors.
        if ($selectorInUse) {
            $origin = if ($r.Row.File -and $FileOrigin.ContainsKey($r.Row.File)) { $FileOrigin[$r.Row.File] } else { $null }
            $configSeverity = if ($setting -and $setting.PSObject.Properties['Severity']) { [string]$setting.Severity } else { $null }
            $miss = Test-MtSelectorMatch -Selection $Selection -Suite $(if ($origin) { [string]$origin.Suite }) -Severity $configSeverity
            if ($miss) {
                $reasons[$r.Key] = New-MtSelectionReason -ReasonCode 'NotSelected' -Detail "Not selected by -$($miss.Selector) ($($miss.Value -join ', '))."
                continue
            }
        }

        # -ExcludeTestId wins over -TestId. A family is excluded here only by a pattern that covers every
        # instance ('MT.1024', 'MT.1024.*'); a pattern for some instances is applied after the run.
        $excludedBy = @(Test-MtIdMatch -Id $matchId -Pattern $Selection.ExcludeTestId)
        if (-not $excludedBy -and $r.ParentId) {
            $excludedBy = @($Selection.ExcludeTestId | Where-Object { $_.Contains('*') -and "$($r.ParentId).*" -like $_ })
        }
        if ($excludedBy) {
            $reasons[$r.Key] = New-MtSelectionReason -ReasonCode 'ExcludedById' -Detail "Excluded by ID ($($excludedBy -join ', '))."
            continue
        }

        if ($Selection.TestId.Count -gt 0) {
            $includedBy = @(Test-MtIdMatch -Id $matchId -Pattern $Selection.TestId)
            if (-not $includedBy -and $r.ParentId) {
                # A pattern for the whole family, or for some of its instances, selects the family; the
                # instances it does not name are reported DeselectedAtRuntime after the run.
                $includedBy = @($Selection.TestId | Where-Object { ($_.Contains('*') -and "$($r.ParentId).*" -like $_) -or $_ -like "$($r.ParentId).*" })
            }
            if (-not $includedBy) {
                $reasons[$r.Key] = New-MtSelectionReason -ReasonCode 'NotSelected' -Detail 'Not in the list of test IDs to run.'
                continue
            }
            $exact = @($includedBy | Where-Object { -not $_.Contains('*') })
            if ($exact) {
                if ($r.Tags -contains 'Preview') { $liftPreview = $true }
                if ($r.Tags -contains 'LongRunning') { $liftLongRunning = $true }
            } else {
                # A wildcard match does not lift the Preview or long-running exclusion.
                if ($r.Tags -contains 'Preview' -and -not $Selection.IncludePreview -and $Selection.Tag.Count -eq 0) {
                    $reasons[$r.Key] = New-MtSelectionReason -ReasonCode 'Preview' -Detail 'Preview test. Use -IncludePreview or name its ID to run it.'
                    continue
                }
                if ($r.Tags -contains 'LongRunning' -and -not $Selection.IncludeLongRunning -and
                    -not (@($Selection.Tag) | Where-Object { $_ -in 'LongRunning', 'CAWhatIf' })) {
                    $reasons[$r.Key] = New-MtSelectionReason -ReasonCode 'LongRunning' -Detail 'Long-running test. Use -IncludeLongRunning or name its ID to run it.'
                    continue
                }
            }
        }
    }

    # IDs named by the user that match no test. Wildcards and family instances are never unknown.
    $named = @($Selection.TestId) + @($Selection.ExcludeTestId) + @($enabledRows.Keys)
    $unknown = foreach ($id in ($named | Where-Object { $_ -and -not $_.Contains('*') } | Select-Object -Unique)) {
        if ($knownIds.Contains($id)) { continue }
        if ($familyParents | Where-Object { $id -eq $_ -or $id -like "$_.*" }) { continue }
        $id
    }

    # Instances of a family that a TestSettings row disables: the family still runs, and these rows become NotRun.
    $disabledInstances = @{}
    foreach ($id in @($enabledRows.Keys)) {
        if ($enabledRows[$id].Enabled -ne $false) { continue }
        if ($familyParents | Where-Object { $id -like "$_.*" }) { $disabledInstances[$id] = $enabledRows[$id] }
    }

    [pscustomobject]@{
        ExcludeLines      = @($reasons.Keys)
        Reasons           = $reasons
        LiftPreview       = $liftPreview
        LiftLongRunning   = $liftLongRunning
        UnknownIds        = @($unknown)
        FamilyParents     = @($familyParents | Select-Object -Unique)
        DisabledInstances = $disabledInstances
    }
}

function New-MtSelectionReason {
    <#
    .SYNOPSIS
    Creates the reason object recorded for a test the engine did not run.
