﻿function Get-MtPreviousResult {
    <#
    .SYNOPSIS
    Returns the result of the previous run on the same tenant, reduced to what a report needs to show changes.

    .DESCRIPTION
    Looks for TestResults-*.json files in -Folder, skipping -Exclude (the file this run writes) and any file that
    is not a Maester result or is for another tenant. Returns ExecutedAt, File (the file name) and Results, a map
    of test ID to result (Passed, Failed, Investigate, Error, Skipped, NotRun), of the newest earlier result, and
    History: the counts of up to -HistoryCount earlier runs, newest first, for the report's trend. Returns nothing
    when there is no earlier result for the tenant.

    Only Id and Result are kept, so the report shows which tests started or stopped failing without carrying a
    second copy of the findings. The comparison is the one Compare-MtTestResult makes. A result file starts with
    its counts, ExecutedAt and TenantId, so History reads only the start of each file; only the newest file is
    read in full.
    #>
    [CmdletBinding()]
    [OutputType([pscustomobject])]
    param(
        # The output folder of the run.
        [Parameter()] [AllowNull()] [AllowEmptyString()] [string] $Folder,

        # The tenant of this run. A result for another tenant is skipped; with no tenant, none is.
        [Parameter()] [AllowNull()] [AllowEmptyString()] [string] $TenantId,

        # Files that are never the previous result, such as the JSON file this run writes.
        [Parameter()] [AllowNull()] [AllowEmptyCollection()] [string[]] $Exclude = @(),

        # How many of the newest files are looked at.
        [Parameter()] [int] $MaxFiles = 15,

        # How many earlier runs History lists.
        [Parameter()] [int] $HistoryCount = 10
    )

    if (-not $Folder -or -not (Test-Path -LiteralPath $Folder -PathType Container)) { return }
    $skip = [System.Collections.Generic.HashSet[string]]::new([System.StringComparer]::OrdinalIgnoreCase)
    foreach ($path in @($Exclude | Where-Object { $_ })) {
        $full = [System.IO.Path]::GetFullPath($path, (Get-Location).Path)
        $null = $skip.Add($full)
    }

    $files = @(Get-ChildItem -LiteralPath $Folder -Filter 'TestResults-*.json' -File -ErrorAction SilentlyContinue |
            Where-Object { -not $skip.Contains($_.FullName) } |
            Sort-Object -Property LastWriteTimeUtc -Descending |
            Select-Object -First $MaxFiles)

    # The start of a result file holds its counts, ExecutedAt and TenantId; the tests come later.
    $headers = foreach ($file in $files) {
        $head = ''
        try {
            $stream = [System.IO.File]::OpenRead($file.FullName)
            try {
                $buffer = [byte[]]::new([math]::Min(8192, $stream.Length))
                $read = $stream.Read($buffer, 0, $buffer.Length)
                $head = [System.Text.Encoding]::UTF8.GetString($buffer, 0, $read)
            } finally { $stream.Dispose() }
        } catch {
            Write-Verbose "Skipping $($file.Name) as a previous result: $($_.Exception.Message)"
            continue
        }
        if ($head -notmatch '"ExecutedAt"\s*:\s*"([^"]+)"') { continue }
        $executedAt = [datetimeoffset]::MinValue
        if (-not [datetimeoffset]::TryParse($Matches[1], [cultureinfo]::InvariantCulture, [System.Globalization.DateTimeStyles]::None, [ref]$executedAt)) { continue }
        if ($TenantId -and $head -match '"TenantId"\s*:\s*"([^"]*)"' -and $Matches[1] -and $Matches[1] -ne $TenantId) { continue }
        $counts = [ordered]@{}
        foreach ($name in 'Total', 'Passed', 'Failed', 'Investigate', 'Error', 'Skipped', 'NotRun') {
            if ($head -match """$($name)Count""\s*:\s*(\d+)") { $counts[$name] = [int]$Matches[1] }
        }
        [pscustomobject]@{ File = $file; ExecutedAt = $executedAt; Counts = $counts }
    }
    $headers = @($headers | Sort-Object -Property ExecutedAt -Descending)

    # The newest earlier result that reads as a Maester result gives the per-test results.
    $previous = $null
    foreach ($header in $headers) {
        try {
            $result = Get-Content -LiteralPath $header.File.FullName -Raw -ErrorAction Stop | ConvertFrom-Json -ErrorAction Stop
        } catch {
            Write-Verbose "Skipping $($header.File.Name) as a previous result: $($_.Exception.Message)"
            continue
        }
        if ($result -isnot [pscustomobject] -or -not $result.PSObject.Properties['Tests']) { continue }
        $previous = [pscustomobject]@{ Header = $header; Result = $result }
        break
    }
    if (-not $previous) { return }

    $results = [ordered]@{}
    foreach ($row in @($previous.Result.Tests)) {
        # A 2.x result has no Id on every row: its Name starts with the ID.
        $id = if ($row.PSObject.Properties['Id'] -and $row.Id) { [string]$row.Id } elseif ($row.PSObject.Properties['Name'] -and [string]$row.Name -match '^([^\s:]+):') { $Matches[1] } else { $null }
        if ($id -and -not $results.Contains($id)) { $results[$id] = [string]$row.Result }
    }
    $history = @($headers | Where-Object { $_.Counts.Contains('Total') } | Select-Object -First $HistoryCount | ForEach-Object {
            $entry = [ordered]@{ ExecutedAt = $_.ExecutedAt.ToString('o', [cultureinfo]::InvariantCulture) }
            foreach ($key in $_.Counts.Keys) { $entry[$key] = $_.Counts[$key] }
            [pscustomobject]$entry
        })
    [pscustomobject][ordered]@{
        ExecutedAt = $previous.Header.ExecutedAt.ToString('o', [cultureinfo]::InvariantCulture)
        File       = $previous.Header.File.Name
        Results    = [pscustomobject]$results
        History    = $history
    }
}
function Merge-MtPartitionResult {
    <#
    .SYNOPSIS
    Merges the partial results of one run split across processes or containers (design section 13.1).

    .DESCRIPTION
    Used by Merge-MtMaesterResult -SameRun. Rows are united by ID; a row that ran replaces a NotRun row
    for the same ID. Rows without an ID are kept as they are. Counts, blocks, the taxonomy names and the run
    result are recomputed, and each partial result's tenant, timing and command are kept under Partitions.
    #>
    [Diagnostics.CodeAnalysis.SuppressMessageAttribute('PSUseShouldProcessForStateChangingFunctions', '', Justification = 'Creates an in-memory object only.')]
    [CmdletBinding()]
    [OutputType([pscustomobject])]
    param(
        [Parameter(Mandatory)]
        [psobject[]] $Results
    )

    $catalogVersions = @($Results | ForEach-Object { if ($_.PSObject.Properties['CatalogVersion']) { [string]$_.CatalogVersion } else { [string]$_.CurrentVersion } } | Select-Object -Unique)
    if ($catalogVersions.Count -gt 1) {
        throw "The partial results come from different catalog versions ($($catalogVersions -join ', ')). Run every partition with the same Maester version."
    }
    $runIds = @($Results | ForEach-Object { if ($_.PSObject.Properties['RunMetadata'] -and $_.RunMetadata -and $_.RunMetadata.PSObject.Properties['RunId']) { [string]$_.RunMetadata.RunId } } | Where-Object { $_ } | Select-Object -Unique)
    if ($runIds.Count -gt 1) {
        throw "The partial results have different RunMetadata.RunId values ($($runIds -join ', ')). Merge only the partitions of one run."
    }

    $byId = [ordered]@{}
    $noId = [System.Collections.Generic.List[object]]::new()
    foreach ($result in $Results) {
        foreach ($row in @($result.Tests)) {
            if (-not $row.Id) { $noId.Add($row); continue }
            $key = [string]$row.Id
            if (-not $byId.Contains($key)) { $byId[$key] = $row; continue }
            $existing = $byId[$key]
            if ($existing.Result -eq 'NotRun' -and $row.Result -ne 'NotRun') {
                $byId[$key] = $row
            } elseif ($existing.Result -ne 'NotRun' -and $row.Result -ne 'NotRun') {
                Write-Warning "Test $key ran in more than one partition; the first result is kept."
            }
        }
    }
    # A partition that did not select a family reports one NotRun row on the parent ID; drop it when
    # another partition ran the family's instances.
    $ranParents = @($byId.Values | Where-Object { $_.Result -ne 'NotRun' -and $_.PSObject.Properties['ParentId'] -and $_.ParentId } | ForEach-Object { [string]$_.ParentId } | Select-Object -Unique)
    foreach ($parent in $ranParents) {
        if ($byId.Contains($parent) -and $byId[$parent].Result -eq 'NotRun') { $byId.Remove($parent) }
    }
    $rows = @($byId.Values) + @($noId)
    $active = @($rows | Where-Object { $_.Result -eq 'Passed' -or $_.Result -eq 'Failed' } | Sort-Object -Property Name)
    $inactive = @($rows | Where-Object { $_.Result -ne 'Passed' -and $_.Result -ne 'Failed' } | Sort-Object -Property Name)
    $rows = @($active) + @($inactive)
    $index = 0
    foreach ($row in $rows) { $index++; if ($row.PSObject.Properties['Index']) { $row.Index = $index } }

    $counters = 'Failed', 'Passed', 'Error', 'Investigate', 'Skipped', 'NotRun'
    $blocks = foreach ($name in @($rows | ForEach-Object { $_.Block } | Where-Object { $_ } | Select-Object -Unique)) {
        $blockRows = @($rows | Where-Object { $_.Block -eq $name })
        $block = [ordered]@{ Name = $name; Result = if ($blockRows | Where-Object { $_.Result -eq 'Failed' }) { 'Failed' } else { 'Passed' } }
        foreach ($counter in $counters) { $block["$($counter)Count"] = @($blockRows | Where-Object { $_.Result -eq $counter }).Count }
        $block.TotalCount = $blockRows.Count
        $previous = $Results | ForEach-Object { $_.Blocks } | Where-Object { $_ -and $_.Name -eq $name } | Select-Object -First 1
        $block.Tag = if ($previous) { $previous.Tag } else { @() }
        [pscustomobject]$block
    }

    $parseDuration = { param($value) $span = [timespan]::Zero; if ($value -and [timespan]::TryParse([string]$value, [ref]$span)) { $span } else { [timespan]::Zero } }
    $longest = ($Results | ForEach-Object { & $parseDuration $_.TotalDuration } | Sort-Object -Descending | Select-Object -First 1)
    $first = $Results[0]
    $partitions = foreach ($result in $Results) {
        [pscustomobject]@{
            TenantId      = $result.TenantId
            TenantContext = if ($result.PSObject.Properties['TenantContext']) { $result.TenantContext } else { $null }
            ExecutedAt    = $result.ExecutedAt
            TotalDuration = $result.TotalDuration
            Result        = $result.Result
            TotalCount    = $result.TotalCount
            InvokeCommand = $result.InvokeCommand
        }
    }
    $unknownIds = @($Results | ForEach-Object { if ($_.PSObject.Properties['Selection'] -and $_.Selection) { $_.Selection.UnknownIds } } | Where-Object { $_ } | Select-Object -Unique)

    $merged = [ordered]@{}
    foreach ($property in $first.PSObject.Properties) { $merged[$property.Name] = $property.Value }
    $merged.Result = if ($Results | Where-Object { $_.Result -eq 'Failed' }) { 'Failed' } elseif ($rows | Where-Object { $_.Result -eq 'Failed' }) { 'Failed' } else { 'Passed' }
    foreach ($counter in $counters) { $merged["$($counter)Count"] = @($rows | Where-Object { $_.Result -eq $counter }).Count }
    $merged.TotalCount = $rows.Count
    $merged.ExecutedAt = ($Results | ForEach-Object { $_.ExecutedAt } | Sort-Object | Select-Object -First 1)
    if ($longest) { $merged.TotalDuration = $longest.ToString('hh\:mm\:ss\.fff') }
    $selections = @($Results | ForEach-Object { if ($_.PSObject.Properties['Selection'] -and $_.Selection) { $_.Selection } })
    $merged.Selection = [pscustomobject]@{
        BuiltIn    = if ($first.PSObject.Properties['Selection'] -and $first.Selection) { $first.Selection.BuiltIn } else { 'All' }
        UnknownIds = $unknownIds
        Superseded = @($Results | ForEach-Object { if ($_.PSObject.Properties['Selection'] -and $_.Selection) { $_.Selection.Superseded } } | Where-Object { $_ })
        # Partitions usually share the tag filter and differ by test IDs; the union shows every tag that applied.
        IncludeTag = @($selections | ForEach-Object { if ($_.PSObject.Properties['IncludeTag']) { $_.IncludeTag } } | Where-Object { $_ } | Select-Object -Unique)
        ExcludeTag = @($selections | ForEach-Object { if ($_.PSObject.Properties['ExcludeTag']) { $_.ExcludeTag } } | Where-Object { $_ } | Select-Object -Unique)
        DryRun     = [bool]($selections | Where-Object { $_.PSObject.Properties['DryRun'] -and $_.DryRun })
    }
    # Each part lists the taxonomy names its own rows use; the merged result lists those of all rows.
    if ($merged.Contains('Taxonomy')) { $merged.Taxonomy = Get-MtResultTaxonomy -InputObject $rows }
    if ($merged.Contains('Frameworks')) { $merged.Frameworks = @(Get-MtResultFramework -InputObject $rows) }
    $packs = @($Results | ForEach-Object { if ($_.PSObject.Properties['Packs']) { $_.Packs } } | Where-Object { $_ } | Group-Object -Property Id | ForEach-Object { $_.Group[0] })
    if ($packs.Count -gt 0) { $merged.Packs = $packs }
    # A part's previous result may be another part of an earlier run, which holds only some of the tests.
    $merged.Remove('Previous')
    $merged.Partitions = @($partitions)
    $merged.Tests = $rows
    $merged.Blocks = @($blocks)
    # EndOfJson stays the last property.
    $merged.Remove('EndOfJson')
    $merged.EndOfJson = 'EndOfJson'
    [pscustomobject]$merged
}

function Add-MtAffectedObjectFact {
    <#
    .SYNOPSIS
    Adds facts about an object, such as its last sign-in or its expired secrets, to the Affected objects page.

    .DESCRIPTION
    Call this from a test, an instance source or a pack that knows more about an object than the checks that name
    it: when the object was last used, which permissions it holds, whether its credentials have expired. The facts
    are shown with the object on the Affected objects page of the HTML report and kept in the AffectedObjects of the
    results, the JSON output and the objects files.

    Add-MtTestResultDetail -GraphObjects says which objects a result is about, and adds them to the page with the check
    that named them. Add-MtAffectedObjectFact says what is known about an object, whichever check named it.

    Facts only describe an object that the run already lists. They are merged into the record with the same System,
    Type and Id when the results are built, so adding facts about an object that no check names adds nothing to the
    report. Facts are collected only while Invoke-Maester collects affected objects; otherwise the call does nothing.

    Each fact has a Name, a Value and a Tone: Risk for something to fix, Warning for something to review, Good for a
    sign that the object is in order, and Info (the default) for anything else.

    A fact can also carry a Key and a Raw value, for code that reads the results: a summary, an insight or another
    report. The Key names what the fact is about, from the shared list of fact keys (user.mfaRegistered,
    signIn.daysSince, device.managed...), so the same fact from two sources means the same thing. Raw is its value as
    data: a boolean, a number, a string, a list of strings or a date, which is kept as an ISO 8601 UTC string. Value
    stays the text people read. Raw is kept only with a Key. A fact without a Key is shown the same way.

    Adding a fact with the same Key, or without a Key the same Name, from the same Source again replaces the earlier one.

    The value is shown as text. Name counts rather than other people where you can: the page shows facts to everyone
    who reads the report, and -RedactUserIdentity replaces only the names of users the run knows.

    .EXAMPLE
    Add-MtAffectedObjectFact -Type ServicePrincipal -Id $sp.id -Source 'Contoso inventory' -Fact @(
        @{ Name = 'Last sign-in'; Value = '2026-06-15 (143 days ago)'; Tone = 'Risk' }
        @{ Name = 'Publisher'; Value = 'Third party (Contoso Ltd)' }
    )

    Adds two facts to an enterprise application.

    .EXAMPLE
    Add-MtAffectedObjectFact -Type User -Id $user.id -Source 'Contoso HR' -Fact @(
        @{ Name = 'MFA'; Value = 'Not registered'; Tone = 'Risk'; Key = 'user.mfaRegistered'; Raw = $false }
        @{ Name = 'Last sign-in'; Value = '2026-06-15 (143 days ago)'; Tone = 'Warning'; Key = 'signIn.daysSince'; Raw = 143 }
    )

    Adds facts with keys, so code can read whether the user has MFA and how long since they signed in without
    parsing the text.

    .EXAMPLE
    $records | Add-MtAffectedObjectFact -Source 'Zero Trust Assessment' -AsOf $report.ExecutedAt

    Adds facts to many objects at once. Each record has Type, Id and Fact properties, and optionally System.

    .LINK
    https://maester.dev/docs/commands/Add-MtAffectedObjectFact

    .LINK
    https://maester.dev/docs/writing-tests/formatting-test-results#adding-facts-about-an-object

    .LINK
    https://maester.dev/docs/writing-tests/formatting-test-results#fact-keys
    #>
    [CmdletBinding()]
    [OutputType([void])]
    param(
        # The object type, as the Affected objects page records it: User, Group, ServicePrincipal, AppRegistration
        # (keyed by its appId), Device, ConditionalAccessPolicy, AgentIdentity, AgentIdentityBlueprint, ConfigurationPolicy...
        [Parameter(Mandatory, ValueFromPipelineByPropertyName)]
        [ValidateNotNullOrEmpty()]
        [string] $Type,

        # The object's id, the same id the record uses (for an app registration, its appId).
        [Parameter(Mandatory, ValueFromPipelineByPropertyName)]
        [ValidateNotNullOrEmpty()]
        [string] $Id,

        # The facts: hashtables or objects with Name, Value, and optionally Tone (Risk, Warning, Good or Info), Key (a
        # shared fact key such as user.mfaRegistered) and Raw (its value as data).
        [Parameter(Mandatory, ValueFromPipelineByPropertyName)]
        [AllowEmptyCollection()]
        [object[]] $Fact,

        # Where the object lives: EntraID (the default), Intune, ExchangeOnline, GitHub...
        [Parameter(ValueFromPipelineByPropertyName)]
        [ValidateNotNullOrEmpty()]
        [string] $System = 'EntraID',

        # What the facts come from, shown with them, for example 'Zero Trust Assessment'.
        [Parameter(Mandatory)]
        [ValidateNotNullOrEmpty()]
        [string] $Source,

        # When the data behind the facts was read, when that is not now (a report written earlier).
        [Parameter()]
        [Nullable[datetime]] $AsOf
    )

    begin {
        $collecting = [bool]$__MtSession.IncludeAffectedObjects
        if (-not $collecting) {
            Write-Verbose 'Add-MtAffectedObjectFact: this run does not collect affected objects, so the facts are not kept.'
            return
        }
        if ($null -eq $__MtSession.AffectedObjectFacts) {
            $__MtSession.AffectedObjectFacts = [System.Collections.Generic.Dictionary[string, System.Collections.Generic.List[object]]]::new([System.StringComparer]::OrdinalIgnoreCase)
        }
        $asOfText = if ($null -ne $AsOf) { $AsOf.ToUniversalTime().ToString('yyyy-MM-ddTHH:mm:ssZ', [cultureinfo]::InvariantCulture) } else { $null }
        $tones = @('Risk', 'Warning', 'Good', 'Info')
        # Dotted camelCase segments: user.mfaRegistered, signIn.daysSince, app.highPrivilegePermissions.
        $keyPattern = '^[a-z][A-Za-z0-9]*(\.[a-z][A-Za-z0-9]*)+$'
        # Raw is kept as JSON-friendly data: a boolean, a number, a string, a list of strings, or a date as ISO text.
        $toRaw = {
            param($Raw, [string] $FactName)
            if ($null -eq $Raw) { return , $null }
            if ($Raw -is [bool] -or $Raw -is [string]) { return , $Raw }
            if ($Raw -is [int] -or $Raw -is [long] -or $Raw -is [double] -or $Raw -is [decimal] -or $Raw -is [single]) { return , $Raw }
            if ($Raw -is [datetime]) { return , $Raw.ToUniversalTime().ToString('yyyy-MM-ddTHH:mm:ssZ', [cultureinfo]::InvariantCulture) }
            if ($Raw -is [datetimeoffset]) { return , $Raw.UtcDateTime.ToString('yyyy-MM-ddTHH:mm:ssZ', [cultureinfo]::InvariantCulture) }
            if ($Raw -is [System.Collections.IEnumerable] -and $Raw -isnot [System.Collections.IDictionary]) {
                return , [string[]]@($Raw | Where-Object { $null -ne $_ } | ForEach-Object { [string]$_ })
            }
            Write-Warning "Add-MtAffectedObjectFact: the Raw value of '$FactName' is a $($Raw.GetType().Name), not a boolean, number, string, list or date, so it is left out."
            return , $null
        }
    }

    process {
        if (-not $collecting) { return }

        $key = '{0}|{1}|{2}' -f $System, $Type, $Id
        $list = $null
        if (-not $__MtSession.AffectedObjectFacts.TryGetValue($key, [ref]$list)) {
            $list = [System.Collections.Generic.List[object]]::new()
            $__MtSession.AffectedObjectFacts[$key] = $list
        }

        foreach ($item in @($Fact)) {
            if ($null -eq $item) { continue }
            $name = [string](Get-ObjectProperty $item 'Name')
            $value = Get-ObjectProperty $item 'Value'
            if ([string]::IsNullOrWhiteSpace($name) -or $null -eq $value -or [string]::IsNullOrWhiteSpace([string]$value)) { continue }
            $tone = [string](Get-ObjectProperty $item 'Tone')
            $tone = if ($tone) { $tones | Where-Object { $_ -eq $tone } | Select-Object -First 1 } else { 'Info' }
            if (-not $tone) {
                Write-Warning "Add-MtAffectedObjectFact: '$name' has the tone '$(Get-ObjectProperty $item 'Tone')', which is not Risk, Warning, Good or Info, so it is shown as Info."
                $tone = 'Info'
            }
            $text = ([string]$value).Trim()
            if ($text.Length -gt 300) { $text = $text.Substring(0, 297) + '...' }

            $factKey = [string](Get-ObjectProperty $item 'Key')
            if ($factKey -and $factKey -cnotmatch $keyPattern) {
                Write-Warning "Add-MtAffectedObjectFact: '$factKey' is not a fact key (dotted camelCase, such as user.mfaRegistered), so '$name' is kept without one."
                $factKey = ''
            }
            # Raw only means something next to a Key, which says how to read it.
            # Read directly: Get-ObjectProperty writes to the pipeline, which turns a one-item list into a string.
            $rawInput = $null
            if ($item -is [System.Collections.IDictionary]) { $rawInput = $item['Raw'] }
            elseif ($item.PSObject.Properties['Raw']) { $rawInput = $item.PSObject.Properties['Raw'].Value }
            $raw = $null
            # Assigned inside the if: an if expression would unroll a list Raw again.
            if ($factKey) { $raw = & $toRaw $rawInput $name }

            $index = if ($factKey) {
                $list.FindIndex({ param($existing) $existing.Key -ceq $factKey -and $existing.Source -eq $Source })
            } else {
                $list.FindIndex({ param($existing) -not $existing.Key -and $existing.Name -eq $name -and $existing.Source -eq $Source })
            }
            $record = [PSCustomObject]@{
                Name   = $name
                Value  = $text
                Tone   = $tone
                Key    = if ($factKey) { $factKey } else { $null }
                Raw    = $raw
                Source = $Source
                AsOf   = $asOfText
            }
            if ($index -ge 0) { $list[$index] = $record } else { $list.Add($record) }
        }
    }
}
