function Get-MtAffectedObject {
    <#
    .SYNOPSIS
    Builds a consolidated affected objects of all objects involved in a Maester test run.

    .DESCRIPTION
    Combines three sources into one normalized inventory:
    1. Structured RelatedObjects captured by Add-MtTestResultDetail (per-test attribution, strongest signal)
    2. Portal deep links parsed from result markdown (covers ad-hoc $portalLink sites and old reports)
    3. Session request caches (run-level view of every Graph/GitHub resource the run touched)

    Records are deduplicated on System/Type/Id; per-test attribution is aggregated
    into a Tests array so each object shows which checks reference it.

    .EXAMPLE
    $results = Invoke-Maester -PassThru
    Get-MtAffectedObject -MaesterResults $results
    #>
    [CmdletBinding()]
    [OutputType([object[]])]
    param(
        # The Maester results object (as produced by ConvertTo-MtMaesterResult / Invoke-Maester -PassThru,
        # or re-hydrated from a TestResults json file). Optional: without it only the session caches are used.
        [Parameter(Mandatory = $false)]
        [psobject] $MaesterResults,

        # Skip the session-cache source (e.g. when analyzing a report file offline).
        [Parameter(Mandatory = $false)]
        [switch] $ExcludeSessionCache
    )

    $records = [System.Collections.Generic.List[object]]::new()

    if ($MaesterResults -and $MaesterResults.Tests) {
        foreach ($test in $MaesterResults.Tests) {
            $detail = $test.ResultDetail
            if (-not $detail) { continue }

            # Source 1: structured records captured before markdown rendering
            foreach ($related in @(Get-ObjectProperty $detail 'RelatedObjects')) {
                if ($null -eq $related) { continue }
                $records.Add([PSCustomObject]@{
                        System            = $related.System
                        AnchorKind        = $related.AnchorKind
                        Type              = $related.Type
                        Id                = $related.Id
                        DisplayName       = $related.DisplayName
                        UserPrincipalName = Get-ObjectProperty $related 'UserPrincipalName'
                        PortalLink        = $related.PortalLink
                        TestId            = $test.Id
                        Source            = $related.Source
                    })
            }

            # Source 2: portal deep links in the rendered markdown
            $markdown = Get-ObjectProperty $detail 'TestResult'
            if (-not [string]::IsNullOrWhiteSpace($markdown)) {
                foreach ($parsed in @(Get-MtAffectedObjectFromMarkdown -Markdown $markdown -TestId $test.Id)) {
                    $records.Add($parsed)
                }
            }
        }
    }

    # Source 3: run-level cache view
    if (-not $ExcludeSessionCache) {
        foreach ($cached in @(Get-MtAffectedObjectFromCache)) {
            $records.Add(($cached | Select-Object *, @{n = 'TestId'; e = { $null } }))
        }
    }

    # Some sources only know a user by UPN (users/{upn} reads, [upn]() links in recommendation
    # results). Key those records by the user's object id when the run saw it, so each user is one
    # object instead of one per identifier.
    $userIdByUpn = [System.Collections.Generic.Dictionary[string, string]]::new([System.StringComparer]::OrdinalIgnoreCase)
    foreach ($record in $records) {
        $userPrincipalName = Get-ObjectProperty $record 'UserPrincipalName'
        if ($record.Type -eq 'User' -and $userPrincipalName -and $record.Id -and -not ([string]$record.Id).Contains('@')) {
            $userIdByUpn[[string]$userPrincipalName] = [string]$record.Id
        }
    }
    if (-not $ExcludeSessionCache -and $__MtSession.GraphCache) {
        foreach ($response in @($__MtSession.GraphCache.Values)) {
            if ($null -eq $response -or $response -is [string]) { continue }
            foreach ($item in @($response) + @($response.value)) {
                if ($null -eq $item -or $item -is [string]) { continue }
                $userPrincipalName = [string](Get-ObjectProperty $item 'userPrincipalName')
                $id = [string](Get-ObjectProperty $item 'id')
                if ($userPrincipalName -and $id -and -not $userIdByUpn.ContainsKey($userPrincipalName)) {
                    $userIdByUpn[$userPrincipalName] = $id
                }
            }
        }
    }
    $userLinkTemplate = (Get-MtPortalLinkTemplate).LinkTemplates.Users
    foreach ($record in $records) {
        $upnKey = [string]$record.Id
        $userId = $null
        if ($record.Type -eq 'User' -and $upnKey.Contains('@') -and $userIdByUpn.TryGetValue($upnKey, [ref] $userId)) {
            $record.Id = $userId
            if (-not $record.PortalLink -and $userLinkTemplate) { $record.PortalLink = $userLinkTemplate -f $userId }
        }
    }

    # Consolidate: one record per System/Type/Id with aggregated test attribution.
    # Structured GraphObjects records win over markdown/cache records for the same object.
    # Unknown sources rank last so a record with a missing Source never outranks a structured one.
    $sourceRank = @{ GraphObjects = 0; Markdown = 1; GraphCache = 2; GitHubCache = 2 }
    # Objects passed without an id fall back to their UPN or name, otherwise distinct users would
    # merge into one object and all but the first would escape redaction.
    $identityOf = {
        param($record)
        if ($record.Id) { return [string]$record.Id }
        $userPrincipalName = Get-ObjectProperty $record 'UserPrincipalName'
        # Bare UPN: the same key a users/{upn} cache read and the signed-in account produce.
        if ($userPrincipalName) { return [string]$userPrincipalName }
        if ($record.DisplayName) { return "name:$($record.DisplayName)" }
        return ''
    }
    # Facts that Add-MtAffectedObjectFact recorded during the run, keyed System|Type|Id. They describe
    # objects the run lists: facts about an object that no source found add no record.
    $factsByKey = $__MtSession.AffectedObjectFacts
    $inventory = $records | Group-Object -Property { "$($_.System)|$($_.Type)|$(& $identityOf $_)" } | ForEach-Object {
        $best = $_.Group | Sort-Object {
            $rank = $sourceRank[[string]$_.Source]
            if ($null -eq $rank) { [int]::MaxValue } else { $rank }
        } | Select-Object -First 1
        $uniqueId = Get-MtAffectedObjectUniqueId -System $best.System -Type $best.Type -Id (& $identityOf $best)
        $facts = $null
        if ($factsByKey -and $best.Id) { $null = $factsByKey.TryGetValue("$($best.System)|$($best.Type)|$($best.Id)", [ref]$facts) }
        [PSCustomObject]@{
            System            = $best.System
            AnchorKind        = $best.AnchorKind
            Type              = $best.Type
            Id                = $best.Id
            UniqueId          = $uniqueId
            # Prefer a real name over a UPN that only stood in for one ([upn]() links, users/{upn} reads).
            DisplayName       = (@($_.Group.DisplayName | Where-Object { $_ }) | Sort-Object { ([string]$_).Contains('@') } | Select-Object -First 1)
            UserPrincipalName = ($_.Group | ForEach-Object { Get-ObjectProperty $_ 'UserPrincipalName' } | Where-Object { $_ } | Select-Object -First 1)
            PortalLink        = ($_.Group.PortalLink | Where-Object { $_ } | Select-Object -First 1)
            Tests             = @($_.Group.TestId | Where-Object { $_ } | Select-Object -Unique)
            Sources           = @($_.Group.Source | Select-Object -Unique)
            Facts             = @($facts | Where-Object { $_ })
        }
    }

    # Assign first: Select-MtAffectedObjectByType returns a comma-forced array, which a direct pipe into
    # Sort-Object would hand over as one object instead of enumerating it.
    $filtered = Select-MtAffectedObjectByType -Objects $inventory

    return @($filtered | Sort-Object System, Type, DisplayName)
}

﻿function Get-MtAffectedObjectFromCache {
    <#
    .SYNOPSIS
    Derives the affected objects from the request caches in the current Maester session.

    .DESCRIPTION
    Walks $__MtSession.GraphCache and $__MtSession.GitHubCache — both keyed by request URL —
    and parses each key into a normalized object record (System / AnchorKind / Type / Id / SourceUri).

    Graph URIs yield:
    - Instance records when a path segment is a GUID (e.g. users/{id}/authentication/methods)
      or a quoted key (e.g. authenticationMethodConfigurations('Fido2'))
    - Singleton records for tenant-level config resources (e.g. policies/authorizationPolicy)
    - Collection records for plain collection reads (e.g. users, servicePrincipals)

    Legacy and metadata GitHub REST cache keys yield External records for the
    organization or repository addressed by the request.

    This is a run-level view (what data the run touched), not per-test attribution.
    #>
    [CmdletBinding()]
    [OutputType([object[]])]
    param()

    $guidPattern = '^[0-9a-fA-F]{8}-([0-9a-fA-F]{4}-){3}[0-9a-fA-F]{12}$'
    # Graph resources that are always tenant-level singletons when read without a key
    $singletonPrefixes = @(
        'policies', 'settings', 'organization', 'admin', 'identityProtection/settings',
        'reports', 'directory/recommendations', 'networkAccess'
    )
    # Graph collections whose keyed reads address a directory object the rest of the inventory
    # already knows under a canonical EntraID type. Mapping them here means a check that both
    # reads users/{id} and renders a portal link produces one object, not two.
    # applications is deliberately absent: the cache keys it by object id while the portal links
    # parsed from markdown carry the app id, so the two would not merge anyway.
    $directoryTypes = @{
        users             = 'User'
        groups            = 'Group'
        devices           = 'Device'
        servicePrincipals = 'ServicePrincipal'
        directoryRoles    = 'DirectoryRole'
    }

    # Keyed reads below these collections address an object the checks also link to under a
    # canonical type, so the read merges with it instead of listing it a second time as a Graph path:
    # accessPackages/{id}/accessPackageResourceRoleScopes is that access package.
    $keyedObjectTypes = @{
        'identityGovernance/entitlementManagement/accessPackages'        = 'AccessPackage'
        'identityGovernance/entitlementManagement/accessPackageCatalogs' = 'AccessPackageCatalog'
    }

    # Action endpoints are verbs, not resources: they address no object worth inventorying.
    $actionSegments = @('$batch', 'runHuntingQuery', 'getMemberGroups', 'getMemberObjects', 'checkMemberGroups')

    $records = [System.Collections.Generic.List[object]]::new()

    if ($__MtSession.GraphCache) {
        foreach ($key in $__MtSession.GraphCache.Keys) {
            # POST cache keys append "_<json body>" (or a bare "_" when the body is empty). A plain
            # underscore is part of the path: guest UPNs look like john_contoso.com#EXT#@tenant.
            $uri = ($key -split '_(?=[\{\[]|$)', 2)[0]
            if ($uri -notmatch '^https://[^/]*graph[^/]*/(v1\.0|beta)/(.+)$') { continue }
            $path = $Matches[2]
            # Strip query string
            $path = ($path -split '\?', 2)[0].TrimEnd('/')
            if ([string]::IsNullOrEmpty($path)) { continue }

            $segments = $path -split '/'
            if ($segments[-1] -in $actionSegments) { continue }

            # A keyed read of a directory collection is the object itself, whatever sub-resource
            # follows: users/{id}/authentication/methods is still that user, not a fifth object.
            # The key may be a GUID or a UPN, and a UPN must be recognised or it lands in Type,
            # where the report's PII redaction never reaches it.
            if ($segments.Count -ge 2 -and $directoryTypes.ContainsKey($segments[0])) {
                # Cache keys are AbsoluteUri values, so a UPN arrives percent-encoded (#EXT# as %23EXT%23).
                $directoryKey = [uri]::UnescapeDataString($segments[1])
            } else {
                $directoryKey = $null
            }
            if ($directoryKey -and ($directoryKey -match $guidPattern -or $directoryKey.Contains('@'))) {
                $records.Add([PSCustomObject]@{
                        System            = 'EntraID'
                        AnchorKind        = 'Instance'
                        Type              = $directoryTypes[$segments[0]]
                        Id                = $directoryKey
                        DisplayName       = $null
                        UserPrincipalName = if ($segments[0] -eq 'users' -and $directoryKey.Contains('@')) { $directoryKey } else { $null }
                        PortalLink        = $null
                        SourceUri         = $uri
                        Source            = 'GraphCache'
                    })
                continue
            }

            $instanceId = $null
            $keyedPath = $null
            $keyName = $null
            $typeSegments = [System.Collections.Generic.List[string]]::new()
            foreach ($segment in $segments) {
                if ($segment -match $guidPattern) {
                    # First key wins: in a/{x}/b/{y} the object is the outer object, not the child.
                    if (-not $instanceId) {
                        $instanceId = $segment
                        $keyedPath = $typeSegments -join '/'
                    }
                } elseif ($segment -match "^(?<res>[^(]+)\((?:(?<keyName>\w+)=)?'(?<key>[^']+)'\)") {
                    # Covers key('x') and alternate keys such as applications(appId='x').
                    $typeSegments.Add($Matches.res)
                    if (-not $instanceId) {
                        $instanceId = $Matches.key
                        $keyedPath = $typeSegments -join '/'
                        $keyName = $Matches.keyName
                    }
                } else {
                    $typeSegments.Add($segment)
                }
            }
            $type = $typeSegments -join '/'

            # Map keyed reads onto the canonical object type. App registrations are keyed by appId
            # everywhere else (portal links use it), so only an appId alternate key maps to one.
            $canonicalType = $null
            if ($instanceId -and $keyedPath -and $keyedObjectTypes.ContainsKey($keyedPath)) {
                $canonicalType = $keyedObjectTypes[$keyedPath]
            } elseif ($instanceId -and $keyedPath -eq 'applications' -and $keyName -eq 'appId') {
                $canonicalType = 'AppRegistration'
            }
            if ($canonicalType) {
                $records.Add([PSCustomObject]@{
                        System            = 'EntraID'
                        AnchorKind        = 'Instance'
                        Type              = $canonicalType
                        Id                = $instanceId
                        DisplayName       = $null
                        UserPrincipalName = $null
                        PortalLink        = $null
                        SourceUri         = $uri
                        Source            = 'GraphCache'
                    })
                continue
            }

            if ($instanceId) {
                $anchorKind = 'Instance'
            } elseif ($singletonPrefixes | Where-Object { $type -eq $_ -or $type.StartsWith("$_/") } | Select-Object -First 1) {
                $anchorKind = 'Singleton'
            } else {
                $anchorKind = 'Collection'
            }

            $records.Add([PSCustomObject]@{
                    System      = 'MicrosoftGraph'
                    AnchorKind  = $anchorKind
                    Type        = $type
                    Id          = $instanceId
                    DisplayName = $null
                    PortalLink  = $null
                    SourceUri   = $uri
                    Source      = 'GraphCache'
                })
        }
    }

    if ($__MtSession.GitHubCache) {
        foreach ($key in $__MtSession.GitHubCache.Keys) {
            # Recognize only the REST namespaces; GraphQL keys contain opaque request data.
            # Pagination options belong to the cache key, never to the resource URI.
            if ($key -match '^Metadata\|GET\|\d{4}-\d{2}-\d{2}\|(?<uri>[^|]+)\|Paginate=(?:True|False)(?:\|MaxPages=[1-9][0-9]*)?$' -or
                $key -match '^\d{4}-\d{2}-\d{2}\|(?<uri>[^|]+)(?:\|MaxPages=[1-9][0-9]*)?$') {
                $uri = $Matches.uri
            } else { continue }
            $parsedUri = $null
            if ($uri -match '\s' -or -not [uri]::TryCreate($uri, [UriKind]::Absolute, [ref]$parsedUri) -or
                $parsedUri.Scheme -ne 'https' -or -not $parsedUri.Host -or $parsedUri.UserInfo -or $parsedUri.Fragment) { continue }
            $path = $parsedUri.AbsolutePath.Trim('/')
            if (-not $path) { continue }
            $segments = $path -split '/'

            $type = $null
            $id = $null
            if ($segments.Count -ge 2 -and $segments[0] -eq 'orgs') {
                $type = 'GitHubOrganization'
                $id = $segments[1]
            } elseif ($segments.Count -ge 3 -and $segments[0] -eq 'repos') {
                $type = 'GitHubRepository'
                $id = "$($segments[1])/$($segments[2])"
            } else {
                $type = 'GitHubResource'
                $id = $path
            }

            $records.Add([PSCustomObject]@{
                    System      = 'GitHub'
                    AnchorKind  = 'External'
                    Type        = $type
                    Id          = $id
                    DisplayName = $id
                    PortalLink  = $null
                    SourceUri   = $uri

}
