        if ([string]$user.userType -eq 'Guest') { 'Guest' } else { 'Member' }
        if ($user.onPremisesSyncEnabled -eq $true) { 'synced from on-premises' }
        if ($user.accountEnabled -eq $false) { 'disabled' }
    ) -join ', '
    $facts.Add((& $newFact 'Account' $account))
