    $last = ConvertTo-MtZtaDate $device.approximateLastSignInDateTime
    if ($last) {
        $facts.Add((& $daysFact $last ((& $daysBefore $last) -gt $staleDays -and $device.accountEnabled -ne $false)))
    }
    & $add 'EntraID' 'Device' $device.id $facts
