            $earlier = $partSteps | Where-Object { $_.Id -eq $s.Id -and $_.PSObject.Properties['Earlier'] -and $_.Earlier } | Select-Object -First 1
            if ($earlier) { $s.Earlier = $earlier.Earlier }
