188	            $tests.Add([pscustomobject][ordered]@{ Id = [string]$row.Id; Result = [string]$row.Result; ReasonCode = $(if (& $field $row 'ReasonCode') { [string](& $field $row 'ReasonCode') } else { $null }) })
189	        }
190	        foreach ($t in @(if ($testsByStep.ContainsKey($id)) { $testsByStep[$id] })) {
191	            $tid = [string]$t.Id
192	            if ($listed.Contains($tid)) { continue }
193	            if ((& $field $t 'InstanceSource') -and $parentsWithRows.Contains($tid)) { continue }
194	            $null = $listed.Add($tid)
195	            $row = if ($rowById.ContainsKey($tid)) { $rowById[$tid] } else { $null }
196	            $tests.Add([pscustomobject][ordered]@{
197	                    Id         = $tid
