200	                })
201	        }
202	        $sortedTests = @($tests | Sort-Object -Property @{ Expression = { ($_.Id -replace '\d+', { $_.Value.PadLeft(10, '0') }) } })
203	
204	        $measure = if ($step.Measure) { & $measureOf $step } else { $null }
205	        $measureRead = $measure -and -not $measure.ReasonCode
206	        $measureUnread = $measure -and $measure.ReasonCode -and $measure.ReasonCode -notin 'MeasureOff', 'NotRead'
207	
208	        $ran = @($sortedTests | Where-Object { $_.Result -ne 'NotRun' })
209	        $counted = @($ran | Where-Object { -not ($_.Result -eq 'Skipped' -and $_.ReasonCode -eq 'NotApplicable') })
210	        $conditions = @($step.OnlyWhen | ForEach-Object { & $conditionOf $_ })
211	
212	        $state = $null; $reason = $null
213	        if ($conditions -contains 'False') { $state = 'NotApplicable'; $reason = 'ConditionNotMet' }
214	        elseif ($conditions -contains 'Unknown') { $state = 'Unknown'; $reason = 'ConditionUnknown' }
215	        elseif ($ran.Count -gt 0 -and $counted.Count -eq 0 -and -not $measureRead) { $state = 'NotApplicable'; $reason = 'TestsNotApplicable' }
216	        elseif (($counted | Where-Object { $_.Result -eq 'Failed' }) -or ($measureRead -and -not $measure.Met)) { $state = 'NotDone' }
217	        else {
218	            $unsure = @($counted | Where-Object { $_.Result -in 'Investigate', 'Error', 'Skipped' })
219	            if ($unsure.Count -gt 0 -or $measureUnread) {
220	                $state = 'Unknown'
