223	            else {
224	                $state = 'NotChecked'
225	                $reason = if ($sortedTests.Count -gt 0) { 'NotSelected' } elseif ($measure -and $measure.ReasonCode -eq 'MeasureOff') { 'MeasureOff' } elseif ($measure) { 'NotRead' } else { 'NoCheck' }
