255	            $open = @($members | Where-Object { $status[$_] -ne 'NotDone' })
256	            if ($open.Count -eq 0) { foreach ($m in $members) { & $addTo $blockedBy $m } }
257	            else { foreach ($m in $open) { & $addTo $unconfirmed $m } }
