261	            if ($status[$other] -eq 'Done') { & $addTo $blockedBy $other }
262	            elseif (& $notMet $other) { & $addTo $unconfirmed $other }
263	        }
264	        $r.BlockedBy = $blockedBy.ToArray()
265	        $r.Unconfirmed = $unconfirmed.ToArray()
266	        $r.Readiness = if ($r.Status -notin 'NotDone', 'Unknown', 'NotChecked') { $null }
267	        elseif ($blockedBy.Count -gt 0) { 'Blocked' }
268	        elseif ($unconfirmed.Count -gt 0) { 'Unconfirmed' }
269	        else { 'Ready' }
270	    }
271	
272	    # Order edges within the scope: a step comes after its prerequisites. Dependents are the reverse.
273	    $prerequisitesOf = @{}
274	    $dependentsOf = @{}
275	    foreach ($id in $scope.Steps) { $dependentsOf[$id] = [System.Collections.Generic.List[string]]::new() }
276	    foreach ($id in $scope.Steps) {
