279	        $prerequisitesOf[$id] = $before
280	        foreach ($p in $before) { if (-not $dependentsOf[$p].Contains($id)) { $dependentsOf[$p].Add($id) } }
281	    }
282	
283	    # Value: own value plus the own values of the NotDone steps that depend on it, at any depth.
284	    $value = @{}
285	    foreach ($id in $scope.Steps) {
286	        $seen = [System.Collections.Generic.HashSet[string]]::new($ordinal)
287	        $queue = [System.Collections.Generic.Queue[string]]::new()
288	        foreach ($d in $dependentsOf[$id]) { $queue.Enqueue($d) }
289	        $unlock = 0.0
290	        while ($queue.Count -gt 0) {
291	            $d = $queue.Dequeue()
292	            if (-not $seen.Add($d)) { continue }
293	            if ($status[$d] -eq 'NotDone') { $unlock += $records[$d].Own }
294	            foreach ($next in $dependentsOf[$d]) { $queue.Enqueue($next) }
295	        }
296	        $value[$id] = $records[$id].Own + $unlock
297	    }
298	
299	    # Rank: by group, then topologically within the group, then by value and ID.
300	    $groupOf = {
301	        param($id)
302	        $r = $records[$id]
303	        switch ($r.Readiness) { 'Ready' { 0 } 'Unconfirmed' { 1 } 'Blocked' { 2 } default { if ($r.Status -eq 'Done') { 3 } else { 4 } } }
304	    }
305	    $rank = 0
306	    foreach ($group in 0..4) {
307	        $members = [System.Collections.Generic.List[string]]::new()
308	        foreach ($id in $scope.Steps) { if ((& $groupOf $id) -eq $group) { $members.Add($id) } }
309	        $placed = [System.Collections.Generic.HashSet[string]]::new($ordinal)
310	        while ($placed.Count -lt $members.Count) {
