316	            if ($available.Count -eq 0) { $available = @($members | Where-Object { -not $placed.Contains($_) }) }
317	            $next = $available | Sort-Object -Property @{ Expression = { $value[$_] }; Descending = $true }, @{ Expression = { $_ } } | Select-Object -First 1
318	            $null = $placed.Add($next)
319	            $rank++
320	            $records[$next].Rank = $rank
321	        }
322	    }
