Describe 'Invoke-MtEngineRun outcomes' {
    It 'Reports <Case> as <Kind>' -ForEach @(
        @{ Case = '$true'; Value = @($true); Kind = 'True' }
        @{ Case = '$false'; Value = @($false); Kind = 'False' }
        @{ Case = '$null'; Value = @($null); Kind = 'Null' }
